comms.text:
@1 וַאֲמַר יְיָ לְאַבְרָם אִיזֵל לָךְ מֵאַרְעָךְ וּמִיַּלָּדוּתָךְ וּמִבֵּית אֲבוּךְ לְאַרְעָא דִּי אַחֲזִנָּךְ:
@2 וְאֶעְבְּדִנָּךְ לְעַם סַגִּי וֶאֱבָרֵכִנָּךְ וַאֲרַבֵּי שְׁמָךְ וּתְהֵא מְבָרֵךְ:
@3 וֶאֱבָרֵךְ מְבָרְכָךְ וּמְלַטְטָךְ אֵילוּט וְיִתְבָּרֲכוּן בְּדִילָךְ כֹּל זַרְעֲיַת אַרְעָא:
@4 וַאֲזַל אַבְרָם כְּמָא דְּמַלֵּיל עִמֵּהּ יְיָ וַאֲזַל עִמֵּהּ לוֹטּ וְאַבְרָם בַּר שִׁבְעִין וַחֲמֵשׁ שְׁנִין בְּמִפְקֵהּ מֵחָרָן:
@5 וּדְבַר אַבְרָם יָת שָׂרַי אִתְּתֵהּ וְיָת לוֹט בַר אֲחוּהִי וְיָת כָּל קִנְיָנְהוֹן דִּי קְנוֹ וְיָת נַפְשָׁתָא דְּשַׁעֲבִּידוּ לְאוֹרַיְתָא בְחָרָן וּנְפָקוּ לְמֵיזַל לְאַרְעָא דִּכְנַעַן וַאֲתוֹ לְאַרְעָא דִּכְנָעַן:
@6 וַעֲבַר אַבְרָם בְּאַרְעָא עַד אֲתַר שְׁכֶם עַד מֵישַׁר מוֹרֶה וּכְנַעֲנָאָה בְּכֵן בְּאַרְעָא:
@7 וְאִתְגְּלִי יְיָ לְאַבְרָם וַאֲמַר לִבְנָךְ אֶתֵּן יָת אַרְעָא הָדָא וּבְנָא תַמָּן מַדְבְּחָא קֳדָם יְיָ דְּאִתְגְּלִי לֵהּ:
@8 וְאִסְתַּלַּק מִתַּמָּן לְטוּרָא מִמַדְנַח לְבֵית אֵל וּפְרַס מַשְׁכְּנֵהּ בֵּית אֵל מִמַּעַרְבָא וְעַי מִמָּדִינְחָא וּבְנָא תַמָּן מִדְבְּחָא קֳדָם יְיָ וְצַלִּי בִּשְׁמָא דַּיְיָ:
@9 וּנְטַּל אַבְרָם אָזֵל וְנָטֵל לְדָרוֹמָא:
@10 וַהֲוָה כַפְנָא בְּאַרְעָא וּנְחַת אַבְרָם לְמִצְרַיִם לְאִתּוֹתָבָא תַמָּן אֲרֵי תַקִּיף כַּפְנָא בְּאַרְעָא:
@11 וַהֲוָה כַּד קְרֵיב לְמֵיעַל לְמִצְרָיִם וַאֲמַר לְשָׂרַי אִתְּתֵה הָא כְעַן יְדָעִית אֲרֵי אִתְּתָא שַׁפִּירַת חֵיזוּ אָתְּ:
@12 וִיהֵי כַּד (נ''י אֲרֵי) יֶחֱזוּן יָתִיךְ מִצְרָאֵי וְיֵימְרוּן אִתְּתֵהּ דָּא וְיִקְטְלוּן יָתִי וְיָתִיךְ יְקַיְמוּן:
@13 אִמְרִי כְעַן אֲחָתִי אָתְּ בְּדִיל דְּיֵיטַב לִי בְּדִילָךְ וְתִתְקַיֵּם נַפְשִׁי בְּפִתְגָּמָיְכִי:
@14 וַהֲוָה כַּד עַל אַבְרָם לְמִצְרָיִם וַחֲזוֹ מִצְרָאֵי יָת אִתְּתָא אֲרֵי שַׁפִּירָא הִיא לַחֲדָא:
@15 וַחֲזוֹ יָתַהּ רַבְרְבֵי פַרְעֹה וְשַׁבָּחוּ יָתַהּ לְפַרְעֹה וְאִדַּבָּרַת אִתְּתָא לְבֵית פַּרְעֹה:
@16 וּלְאַבְרָם אוֹטִיב בְּדִילַהּ וַהֲווֹ לֵהּ עָאן וְתוֹרִין וַחֲמָרִין וְעַבְדִין וְאַמְהָן וְאַתְנָן וְגַמְלִין:
@17 וְאַיְתִי יְיָ עַל פַּרְעֹה מַכְתָּשִׁין רַבְרְבִין וְעַל אֱנַשׁ בֵּיתֵהּ עַל עֵיסַק שָׂרַי אִתַּת אַבְרָם:
@18 וּקְרָא פַרְעֹה לְאַבְרָם וַאֲמַר מָה דָּא עֲבַדְתְּ לִי לְמָא לָא חַוֵּיתָא לִי אֲרֵי אִתְּתָךְ הִיא:
@19 לְמָא אֲמַרְתְּ אֲחָתִי הִיא וּדְבָרִית יָתַהּ לִי לְאִתּוּ וּכְעַן הָא אִתְּתָךְ דְּבַר וְאִיזֵל:
@20 וּפַקִּיד עֲלוֹהִי פַּרְעֹה גּוּבְרִין וְאַלְוִיאוּ יָתֵהּ וְיָת אִתְּתֵהּ וְיָת כָּל דִילֵהּ:
@21 וּסְלֵיק אַבְרָם מִמִּצְרַיִם הוּא וְאִתְּתֵהּ וְכָל דִּילֵהּ וְלוֹט עִמֵּהּ לְדָרוֹמָא:
@22 וְאַבְרָם תַּקִּיף לַחֲדָא בִּבְעִירָא בְּכַסְפָּא וּבְדַהֲבָא:
@23 וַאֲזַל לְמַטְלָנוֹהִי מִדָּרוֹמָא וְעַד בֵּית אֵל עַד אַתְרָא דִּי פְּרַס תַּמָּן מַשְׁכְּנֵהּ בְּקַדְמֵיתָא בֵּין בֵּית אֵל וּבֵין עָי:
@24 לַאֲתַר מַדְבְּחָא דִּי עֲבַד תַּמָּן בְּקַדְמֵיתָא וְצַלֵּי תַמָּן אַבְרָם בִּשְׁמָא דַּיְיָ:
@25 וְאַף לְלוֹט דְּאָזִיל עִם אַבְרָם הֲוָה עָאן וְתוֹרִין וּמַשְׁכְּנִין:
@26 וְלָא סוֹבָרַת יָתְהוֹן אַרְעָא לְמִיתַב כַּחֲדָא אֲרֵי הֲוָה קִנְיָנְהוֹן סַגִּי וְלָא יְכִילוּ לְמִיתַּב כַּחֲדָא:
@27 וַהַוַת מַצוּתָא בֵּין רָעֵי בְּעִירֵה דְאַבְרָם וּבֵין רָעֵי בְּעִירֵה דְלוֹט וּכְנַעֲנָאָה וּפְרִזָאָה בְּכֵן יָתִיב בְּאַרְעָא:
@28 וַאֲמַר אַבְרָם לְלוֹט לָא כְעַן תְּהֵי מַצוּתָא בֵּינָא וּבֵינָךְ וּבֵין רַעֲוָתִי וּבֵין רַעֲוָתָךְ אֲרֵי גוּבְרִין אַחִין אֲנָחְנָא:
@29 הֲלָא כָל אַרְעָא קֳדָמָךְ אִתְפָּרַשׁ כְּעַן מִלְוָתִי אִם אַתְּ לְצִפּוּנָא וַאֲנָא לְדָרוֹמָא וְאִם אַתְּ לְדָרוֹמָא וַאֲנָא לְצִפּוּנָא:
@30 וּזְקַף לוֹט יָת עֵינוֹהִי וַחֲזָא יָת כָּל מֵישַׁר יַרְדְנָא אֲרֵי כֻלַהּ בֵּית שַׁקְיָא קֳדָם חַבָּלוּת יְיָ יָת סְדוֹם וְיָת עֲמֹרָא כְּגִנְתָא דַיְיָ כְּאַרְעָא דְמִצְרַיִם מָטֵּי לְצוֹעַר:
@31 וּבְחַר לֵיהּ לוֹט יַת כָּל מֵישַׁר יַרְדְנָא וּנְטַל לוֹט מִלְקַדְמִין וְאִתַּפְרָשׁוּ גְבַר מִלְוַת אָחוּהִי:
@32 אַבְרָם יָתֵיב בְּאַרְעָא דִכְנָעַן וְלוֹט יָתֵיב בְּקִרְוֵי מֵישְׁרָא וּפְרַס עַד סְדוֹם:
@33 וֶאֱנָשִׁין דִסְדוֹם בִּישִׁין בְּמָמוֹנְהוֹן וְחַיָבִין בִּגְוִיָתְהוֹן קֳדָם יְיָ לַחֲדָא:
@34 וַיְיָ אֲמַר לְאַבְרָם בָּתַר דְאִתְפָּרֶשׁ לוֹט מֵעִמֵהּ זְקוֹף כְּעַן עֵינָךְ וַחֲזֵי מִן אַתְרָא דְאַתְּ תַּמָן לְצִפּוּנָא וּלְדָרוֹמָא וּלְמַדִינְחָא וּלְמַעֲרָבָא:
@35 אֲרֵי יָת כָּל אַרְעָא דִי אַתְּ חָזֵי לָךְ אֶתְּנִנַהּ וְלִבְנָיךְ עַד עָלָם:
@36 וֶאֱשַׁוֵּי יָת בְּנָיךְ סַגִיאִין כְּעַפְרָא דְאַרְעָא כְּמָא דִי לָא אֶפְשַׁר לִגְבַר לְּמִמְנֵי יָת עַפְרָא דְאַרְעָא אַף בְּנָיךְ לָא יִתִּמְנוּן:
@37 קוּם הֲלִיךְ בְּאַרְעָא לְאָרְכַּהּ וְלִפְתָיַהּ אֲרֵי לָךְ אֶתְּנִינַהּ:
@38 וּפְרַס אַבְרָם וַאֲתָא וִיתֵב בְּמֵישְׁרֵי מַמְרֵא דִי בְחֶבְרוֹן וּבְנָא תַמָן מַדְבְּחָא קֳדָם יְיָ:
@39 וַהֲוָה בְיוֹמֵי אַמְרָפֶל מַלְכָּא דְבָבֶל אַרְיוֹךְ מַלְכָּא דְאֶלָסָר כְּדָרְלָעוֹמֶר מַלְכָּא דְעֵילָם וְתִדְעָל מַלְכָּא דְעַמְמֵי:
@40 סְדָרוּ (נ''א עֲבָדוּ) קְרָבָא עִם בֶּרַע מַלְכָּא דִסְדוֹם וְעִם בִּרְשַׁע מַלְכָּא דַעֲמֹרָה שִׁנְאָב מַלְכָּא דְאַדְמָה וְשֶׁמְאֵבֶר מַלְכָּא דִצְבוֹיִם וּמַלְכָּא דְבֶלַּע הִיא צוֹעַר:
@41 כָּל אִלֵין אִתְכְּנָשׁוּ לְמֵישַׁר חַקְלַיָא הוּא אֲתַר יַמָא דְמִלְחָא:
@42 תַּרְתֵּי עַשְׂרֵי שְׁנִין פְּלָחוּ יָת כְּדָרְלָעוֹמֶר וּתְלָת עֶשְׂרֵי שְׁנִין מְרָדוּ:
@43 וּבְאַרְבַּע עֶשְׂרֵי שְׁנִין אֲתָא כְּדָרְלָעֹמֶר וּמַלְכַיָא דְעִמֵהּ וּמְחוֹ יָת גִבָּרַיָא דִי בְעַשְׁתְּרוֹת קַרְנַיִם וְיָת תַּקִיפַיָא דִבְהֶמְתָּא וְיָת אֵמְתָנֵי דִבְשָׁוֵה קִרְיָתָיִם:
@44 וְיָת חוֹרָאֵי דִי בְּטוּרְהוֹן דְשֵׂעִיר עַד מֵישַׁר פָּארָן דִסְמִיךְ עַל מַדְבְּרָא:
@45 וְתָבוּ וַאֲתוּ לְמֵישַׁר פִּלּוּג דִינָא הִיא רְקָם וּמְחוֹ יָת כָּל חֲקַל עֲמַלְקָאָה וְאַף יָת אֱמוֹרָאָה דְיָתֵיב בְּעֵין גֶּדִי:
@46 וּנְפַק מַלְכָּא דִסְדוֹם וּמַלְכָּא דַעֲמוֹרָה וּמַלְכָּא דְאַדְמָה וּמַלְכָּא דִצְבוֹיִם וּמַלְכָּא דְבֶלַע הִיא צוֹעַר וְסַדָרוּ עִמְהוֹן קְרָבָא בְּמֵישַׁר חַקְלַיָא:
@47 עִם כְּדָרְלָעֹמֶר מַלְכָּא דְעֵילָם וְתִדְעָל מַלְכָּא דְעַמְמִין וְאַמְרָפֶל מַלְכָּא דְבָבֶל וְאַרְיוֹךְ מַלְכָּא דְאֶלָסָר אַרְבְּעָה מַלְכִין לָקֳבֵיל חַמְשָׁא:
@48 וּמֵישַׁר חַקְלַיָא בֵּירִין בֵּירִין מַסְקַן חֵימָרָא וַעֲרָקוּ מַלְכָּא דִסְדוֹם וַעֲמוֹרָה וּנְפָלוּ תַמָן וּדְאִשְׁתָּאֲרוּ לְטוּרָא עֲרָקוּ:
@49 וּשְׁבוֹ יָת כָּל קִנְיָנָא דִסְדוֹם וַעֲמוֹרָה וְיָת כָּל מֵיכָלְהוֹן וַאֲזָלוּ:
@50 וּשְׁבוֹ יָת לוֹט וְיָת קִנְיָנֵהּ בַּר אַחוּהִי דְאַבְרָם וַאֲזָלוּ וְהוּא יָתֵיב בִּסְדוֹם:
@51 וַאֲתָא מְשֵׁיזָבָא וְחַוִּי לְאַבְרָם עִבְרָאָה וְהוּא שָׁרֵי בְּמֵישְׁרֵי מַמְרֵא אֱמוֹרָאָה אֲחוּהִי דְאֶשְׁכּוֹל וַאֲחוּהִי דְעָנֵר וְאִינוּן אֱנָשֵׁי קְיָמֵהּ דְאַבְרָם:
@52 וּשְׁמַע אַבְרָם אֲרֵי אִשְׁתְּבִי אֲחוּהִי וְזָרֵיז יָת עוּלֵמוֹהִי יְלִידֵי בֵיתֵהּ תְּלַת מְאָה וְתַמְנֵי עֲסַר וּרְדַף עַד דָן:
@53 וְאִתְפְּלֵג עֲלֵיהוֹן לֵילְיָא הוּא וְעַבְדוֹהִי וּמְחוֹנוּן וּרְדָפִנוּן עַד חוֹבָא דִי מִצִפּוּנָא לְדַמָשֶׂק:
@54 וַאֲתֵיב יָת כָּל קִנְיָנָא וְאַף יָת לוֹט בַּר אֲחוּהִי וְקִנְיָנֵהּ אֲתֵיב וְאַף יָת נְשַׁיָא וְיָת עַמָא:
@55 וּנְפַק מַלְכָּא דִסְדוֹם לְקַדָמוּתֵה בָּתַר דְתָב מִלְמִמְחֵי יָת כְּדָרְלָעוֹמֶר וְיָת מַלְכַיָא דִי עִמֵהּ לְמֵישַׁר מַפְנָא הוּא אֲתַר בֵּית רֵיסָא דְמַלְכָּא:
@56 וּמַלְכִּי צֶדֶק מַלְכָּא דִירוּשְׁלֶם אַפֵּיק לְחֵם וַחֲמָר וְהוּא מְשַׁמֵשׁ קֳדָם אֵל עִלָאָה:
@57 וּבָרְכֵיהּ וַאֲמָר בְּרִיךְ אַבְרָם לְאֵל עִלָאָה דְקִנְיָנֵהּ שְׁמַיָא וְאַרְעָא:
@58 וּבְרִיךְ אֵל עִלָאָה דִמְסַר סָנְאָיךְ בִּידָךְ וִיהַב לֵיהּ חַד מִן עַשְׂרָא מִכֹּלָא:
@59 וַאֲמַר מַלְכָּא דִסְדוֹם לְאַבְרָם הַב לִי נַפְשָׁתָא וְקִנְיָנָא (סַב) דְבַר לָךְ:
@60 וַאֲמַר אַבְרָם לְמַלְכָּא דִסְדוֹם אֲרֵמִית יְדַי בִּצְלוֹ קֳדָם יְיָ אֵל עִלָאָה דְקִנְיָנֵהּ שְׁמַיָא וְאַרְעָא:
@61 אִם מִחוּטָא וְעַד עַרְקַת מְסָנָא וְאִם אֶסַב מִכָּל דִי לָךְ וְלָא תֵימַר אֲנָא אַעְתָּרִית יָת אַבְרָם:
@62 לְחוֹד (בַּר) מִדִאֲכָלוּ עוּלֵמַיָא וְחָלָק גֻבְרַיָא דִי אֲזָלוּ עִמִי עָנֵר אֶשְׁכּוֹל וּמַמְרֵא אִינוּן יְקַבְּלוּן חַלָקְהוֹן:
@63 בָּתַר פִּתְגָמַיָא הָאִלֵין הֲוָה פִּתְגָמָא דַיְיָ עִם אַבְרָם בִּנְבוּאָה לְמֵימָר לָא תִדְחַל אַבְרָם מֵימְרִי תְּקוֹף לָךְ אַגְרָךְ סַגִי לַחֲדָא:
@64 וַאֲמַר אַבְרָם יְיָ אֱלֹהִים מַה תִּתֶּן לִי וַאֲנָא אָזֵיל בְּלָא וְלָד וּבַר פַּרְנָסָא הָדֵין דִבְּבֵיתִי הוּא דַמַשְׂקָאָה אֱלִיעֶזֶר:
@65 וַאֲמַר אַבְרָם הָא לִי לָא יְהַבְתְּ וְלָד וְהָא בַר בֵיתִי יָרִיתּ יָתִי:
@66 וְהָא פִּתְגָמָא דַיְיָ עִמֵהּ לְמֵימַר לָא יִרְתִינָךְ דֵין אֱלָהֵין בַּר דְתוֹלִיד הוּא יִרְתִינָךְ:
@67 וְאַפֵּיק יָתֵהּ לְבָרָא וַאֲמַר אִסְתְּכִי כְעַן לִשְׁמַיָא וּמְנֵי כּוֹכְבַיָא אִם תִּכּוֹל לְמִמְנֵי יָתְהוֹן וַאֲמַר לֵיהּ כְּדֵין יְהוֹן בְּנָךְ:
@68 וְהֵימִין בְּמֵימְרָא דַיְיָ וְחָשְׁבַהּ לֵיהּ לְזָכוּ:
@69 וַאֲמַר לֵהּ אֲנָא יְיָ דְאַפֵּקְתָּךְ מֵאוּרָא דְכַשְׂדָאֵי לְמִתַּן לָךְ יָת אַרְעָא הָדָא לְמֵירְתַהּ:
@70 וַאֲמָר יְיָ אֱלֹהִים בְּמָה אִידַע אֲרֵי אֵרְתִנַהּ:
@71 וַאֲמַר לֵהּ קָרֵב קֳדָמַי עֶגְלִין תְּלָתָא וְעִזִין תְּלָתָא וְדִכְרִין תְּלָת וְשַׁפְנִינָא וּבַר יוֹנָה:
@72 וְקָרֵב קֳדָמוֹהִי יָת כָּל אִלֵין וּפַלִיג יָתְהוֹן בְּשָׁוֶה וִיהַב פַּלְגַיָא פִּלוּג לָקֳבֵיל חַבְרֵיהּ וְיָת עוֹפָא לָא פַּלִיג:
@73 וּנְחַת עוֹפָא עַל פַּגְלַיָא וְאַפְרַח יָתְהוֹן אַבְרָם:
@74 וַהֲוָה שִׁמְשָׁא לְמֵיעַל וְשִׁינְתָא נְפָלַת עַל אַבְרָם וְהָא אֵימָתָא קְבֵל סַגִי נְפָלַת עֲלוֹהִי:
@75 וַאֲמַר לְאַבְרָם מִדַע תִּדַע אֲרֵי דַיָרִין יְהוֹן בְּנָיךְ בְּאַרְעָא דְלָא דִילְהוֹן וְיִפְלְחוּן בְּהוֹן וִיעַנוּן יָתְהוֹן אַרְבַּע מְאָה שְׁנִין:
@76 וְאַף יָת עַמָא דְיִפְלְחוּן בְּהוֹן דָיִין אֲנָא וּבָתַר כֵּן יִפְקוּן בְּקִנְיָנָא סַגִי:
@77 וְאַתְּ תֵעוֹל לְוָת אַבָהָתָךְ בִּשְׁלָם תִּתְקְבַר בְּסֵיבוּ טָבָא:
@78 וְדָרָא רְבִיעָאָה יְתוּבוּן הָכָא אֲרֵי לָא שְׁלִים חוֹבָא דֶאֱמוֹרָאָה עַד כְּעָן:
@79 וַהֲוָה שִׁמְשָׁא עַלַת וְקִבְלָא הֲוָה וְהָא תַּנוּר דִתְנַן וּבָעוּר דְאֶשָׁתָא דִעֲדָא בֵּין פַּלְגַיָא הָאִלֵין:
@80 בְּיוֹמָא הַהוּא גְזַר יְיָ עִם אַבְרָם קְיָם לְמֵימָר לִבְנָךְ יְהָבִית יָת אַרְעָא הָדָא מִן נַהֲרָא דְמִצְרַיִם וְעַד נַהֲרָא רַבָּא נַהֲרָא פְרָת:
@81 יָת שַׁלְמָאֵי וְיָת קְנִזָאֵי וְיָת קַדְמוֹנָאֵי:
@82 וְיָת חִתָּאֵי וְיָת פְּרִזָאֵי וְיָת גִבָּרָאֵי:
@83 וְיָת אֱמוֹרָאֵי וְיָת כְנַעֲנָאֵי וְיָת גִרְגָשָׁאֵי וְיָת יְבוּסָאֵי:
@84 וְשָׂרַי אִתַּת אַבְרָם לָא יְלִידַת לֵהּ וְלַהּ אַמְתָא מִצְרֵיתָא וּשְׁמַהּ הָגָר:
@85 וַאֲמַרַת שָׂרַי לְאַבְרָם הָא כְעַן מַנְעֲנִי יְיָ מִלְמֵילַד עוּל כְּעַן לְוַת אַמְתִי מָאִים אִתְבְּנֵי מִנַהּ וְקַבִּיל אַבְרָם לְמֵימַר שָׂרָי:
@86 וּדְבָרַת שָׂרַי אִתַּת אַבְרָם יָת הָגָר מִצְרֵיתָא אַמְתַהּ מִסוֹף עֲשַׂר שְׁנִין לְמִיתַּב אַבְרָם בְּאַרְעָא דִכְנָעַן וִיהָבַת יָתַהּ לְאַבְרָם בַּעֲלַהּ לֵהּ לְאִנְתּוּ:
@87 וְעַל לְוַת הָגָר וְעַדִיאַת וַחֲזַת אֲרֵי עֲדִיאַת וּקְלַת רִבָּנְתַּהּ בְּעֵינָהַהּ:
@88 וַאֲמַרַת שָׂרַי לְאַבְרָם דִין לִי עֲלָךְ אֲנָא יְהָבִית אַמְתִי לָךְ וַחֲזַת אֲרֵי עֲדִיאַת וּקְלֵית בְּעֵינָהַהּ יְדִין יְיָ בֵּינִי וּבֵינָךְ:
@89 וַאֲמַר אַבְרָם לְשָׂרַי הָא אַמְתִיךְ בִּידִךְ עִבִידִי לַהּ כִּדְתַקִין בְעֵינָיְכִי וְעֲנִיתַהּ שָׂרַי וְעָרְקַת מִקֳדָמָהַהּ:
@90 וְאַשְׁכְּחַהּ מַלְאָכָא דַיְיָ עַל עֵינָא דְמַיָא בְּמַדְבְּרָא עַל עֵינָא בְּאָרְחָא דְחַגְרָא:
@91 וַאֲמַר הָגָר אַמְתָא דְשָׂרַי מְנָן אַתְּ אָתְיָא וּלְאָן אַתְּ אָזְלָא וַאֲמַרַת מִן קֳדָם שָׂרַי רִבָּנְתִּי אֲנָא עֲרָקָא (עֲרָקַת):
@92 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ תּוּבִי לְוַת רִבּוֹנְתִּיךְ וְאִשְׁתַּעְבְּדִי תְּחוֹת יְדָהָא:
@93 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ אַסְגָאָה אַסְגֵי יָת בְּנָיְכִי וְלָא יִתִּמְנוּן מִסְגֵי:
@94 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ הָא אַתְּ מְעַדְיָא וְתֵלְדִין בַּר וְתִקְרִין שְׁמֵהּ יִשְׁמָעֵאל אֲרֵי קַבִּיל יְיָ צְלוֹתִיךְ:
@95 וְהוּא יְהֵא מָרוֹד בֶּאֱנָשָׁא הוּא יְהֵא צְרִיךְ לְכֹלָא וְאַף כָּל בְנֵי אֲנָשָׁא יְהוֹן צְרִיכִין לֵהּ וְעַל אַפֵּי כָל אֲחוֹהִי יִשְׁרֵי:
@96 וְצַלִיאַת בִּשְׁמָא דַיְיָ דְמִתְמַלֵל עִמַהּ אֲמַרַת אַתְּ הוּא אֱלָהָא דְחָזֵי כֹלָא אֲרֵי אֲמַרַת הַבְרַם הָכָא (נ''א הַאַף אֲנָא) שָּׁרֵיתִי חַזְיָא בָּתַר דְאִתְגְלִי לִי:
@97 עַל כֵּן קְרָא לִבְאֵרָא בְּאֵרָא דְמַלְאַךְ קַיָימָא אִתַּחֲזִי עֲלַהּ הָא הִיא בֵּין רְקָם וּבֵין חַגְרָא:
@98 וִילִידַת הָגָר לְאַבְרָם בָּר וקְרָא אַבְרָם שׁוּם בְּרֵיהּ דִילִידַת הָגָר יִשְׁמָעֵאל:
@99 וְאַבְרָם בַּר תְּמָנָן וְשִׁית שְׁנִין כַּד יְלִידַת הָגָר יָת יִשְׁמָעֵאל לְאַבְרָם:
@100 וַהֲוָה אַבְרָם בַּר תִּשְׁעִין וּתְשַׁע שְׁנִין וְאִתְגְלִי יְיָ לְאַבְרָם וַאֲמַר לֵיהּ אֲנָא אֵל שַׁדַי פְּלַח קֳדָמַי וֶהֱוֵי שְׁלִים:
@101 וְאֶתֵּן קְיָמִי בֵּין מֵימְרִי וּבֵינָךְ וְאַסְגֵי יָתָךְ לַחֲדָא לַחֲדָא:
@102 וּנְפַל אַבְרָם עַל אַפּוֹהִי וּמַלֵיל עִמֵהּ יְיָ לְמֵימָר:
@103 אֲנָא הָא (גְזַר) קְיָמִי עִמָךְ וּתְהֵי לְאַב סַגִי עַמְמִין:
@104 וְלָא יִתְקְרֵי עוֹד יָת שְׁמָּךְ אַבְרָם וִיהֵי שְׁמָךְ אַבְרָהָם אֲרֵי אַב סַגִי עַמְמִין יְהָבִתָךְ:
@105 וְאַפִּישׁ יָתָךְ לַחֲדָא לַחֲדָא וְאֶתְּנִנָךְ לְכִנְשִׁין וּמַלְכִין דְשַׁלִיטִין בְּעַמְמַיָא מִנָךְ יִפְקוּן:
@106 וַאַקֵים יָת קְיָמִי בֵּין מֵימְרִי וּבֵינָךְ וּבֵין בְּנָךְ בַּתְרָךְ לְדָרֵיהוֹן לִקְיָם עָלָם לְמֵהֲוֵי לָךְ לֵאלָהָא וְלִבְנָיךְ בַּתְרָךְ:
@107 וְאֶתֵּן לָךְ וְלִבְנָיךְ בַּתְרָךְ יָת אַרְעָא תּוֹתָבוּתָךְ יָת כָּל אַרְעָא דִכְנַעַן לְאַחֲסָנַת עָלָם וְאֱהֶוֵי לְהוֹן לֵאלָהָא:
@108 וַאֲמַר יְיָ לְאַבְרָהָם וְאַתְּ יָת קְיָמִי תִטָר אַתְּ וּבְנָךְ בַּתְרָךְ לְדָרֵיהוֹן:
@109 דָא קְיָמִי דִי תִטְרוּן בֵּין מֵימְרִי וּבֵינֵיכוֹן וּבֵין בְּנָיךְ בַּתְרָךְ מִגְזַר לְכוֹן כָּל דְכוּרָא:
@110 וְתִגְזְרוּן יָת בִּשְׂרָא דְעָרְלָתְכוֹן וּתְהֵי (נ''י וּתְהֵא) לְאָת קְיָם בֵּין מֵימְרִי וּבֵינֵיכוֹן:
@111 וּבַר תְּמַנְיָא יוֹמִין יִתְגְזַר (יִגְזַר) לְכוֹן כָּל דְכוּרָא לְדָרָתֵיכוֹן יְלִידֵי בֵּיתָא וּזְבִינֵי כַּסְפָּא מִכֹּל בַּר עַמְמִין דְלָא מִבְּנָךְ הוּא:
@112 אִתְגַזָרָא יִתְגַזְרוּן (נ''י מִגְזַר יִגְזַר) יְלִיד בֵּיתָךְ וּזְבִין כַּסְפָּךְ וּתְהֵי קְיָמִי בְּבִשְׂרֵיכוֹן לִקְיָם עָלָם:
@113 וְעָרֵל דְכוּרָא דִי לָא יִגְזַר יָת בְּשַׂר עָרְלָתֵהּ וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמֵּיהּ יָת קְיָמִי אַשְׁנִי:
@114 וַאֲמַר יְיָ לְאַבְרָהָם שָׂרַי אִתְּתָךְ לָא תִקְרֵי יָת שְׁמַהּ שָׂרָי אֲרֵי שָׂרָה שְׁמַהּ:
@115 וֶאֱבָרֵךְ יָתַהּ וְאַף אֶתֵּן מִנַהּ לָךְ בָּר וֶאֱבָרֲכִנַהּ וּתְהֵי לְכִנְשִׁין מַלְכִין דְשַׁלִּיטִין בְעַמְמַיָּא מִנַהּ יְהוֹן:
@116 וּנְפַל אַבְרָהָם עַל אַפּוֹהִי וַחֲדִי וַאֲמַר בְּלִבֵּהּ הַלְּבַר מְאָה שְׁנִין יְהֵי וְלַד וְאִם שָׂרָה הֲבַת תִּשְׁעִין שְׁנִין תְּלִיד:
@117 וַאֲמַר אַבְרָהָם קֳדָם יְיָ לְוַי יִשְׁמָעֵאל יִתְקַיָּם קֳדָמָךְ:
@118 וַאֲמַר יְיָ בְּקוּשְׁטָא שָׂרָה אִתְּתָךְ תְּלִיד לָךְ בָּר וְתִקְרֵי יָת שְׁמֵהּ יִצְחָק וַאֲקִים יָת קְיָמִי עִמֵּהּ לִקְיָם עָלָם לִבְנוֹהִי בַּתְרוֹהִי:
@119 וְעַל יִשְׁמָעֵאל קַבֵּלִית צְלוֹתָךְ הָא בָּרֵכִית יָתֵהּ וְאַפֵּישּׁ יָתֵהּ וְאַסְגֵּי יָתֵהּ לַחֲדָא לַחֲדָא תְּרֵין עֲשַׂר רַבְרְבַיָּא יְלִיד וְאֶתְּנִנֵּיהּ לְעַם סַגִּי:
@120 וְיָת קְיָמִי אָקִים עִם יִצְחָק דִי תְלִיד לָךְ שָׂרָה לְזִמְנָא הָדֵין בְּשַׁתָּא אָחֳרַנְתָּא:
@121 וְשֵׁיצֵי לְמַלָּלָא עִמֵהּ וְאִסְתַּלַּק יְקָרָא דַיְיָ מֵעִלָּווֹהִי דְּאַבְרָהָם:
@122 וּדְבַר אַבְרָהָם יָת יִשְׁמָעֵאל בְּרֵהּ וְיָת כָּל יְלִידֵי בֵיתֵהּ וְיָת כָּל זְבִינֵי כַסְפֵּה כָּל דְּכוּרָא בַּאֲנָשֵׁי בֵּית אַבְרָהָם וּגְזַר יָת בִּשְׂרָא דְעָרְלָתְהוֹן בִּכְרַן יוֹמָא הָדֵין כְּמָא דִי מַלֵיל עִמֵּהּ יְיָ:
@123 וְאַבְרָהָם בַּר תִּשְׁעִין וּתְשַׁע שְׁנִין כַּד גְזַר בִּשְׂרָא דְעָרְלְתֵהּ:
@124 וְיִשְׁמָעֵאל בְּרֵהּ בַּר תְּלַת עַשְׂרֵי שְׁנִין כַּד גְּזַר יַת בִּשְׂרָא דְעָרְלְתֵהּ:
@125 בִּכְרַן יוֹמָא הָדֵין (גְּזַר) אִתְגְּזַר אַבְרָהָם וְיִשְׁמָעֵאל בְּרֵהּ:
@126 וְכָל אֱנָשֵׁי בֵיתֵהּ יְלִידֵי בֵיתָא וּזְבִינֵי כַסְפָּא מִן בַּר עַמְמִין אִתְגְּזָרוּ (גְזָרוּ) עִמֵּהּ: פפפ:

@1 **לך לך.** להנאתך ולטובתך, ושם אעשך לגוי גדול, וכאן אי אתה זוכה לבנים. ועוד שאודיע טבעך בעולם:
@2 **ואעשך לגוי גדול.** לפי שהדרך גורמת לשלשה דברים ממעטת פריה ורביה, וממעטת את הממון, וממעטת את השם, לכך הזקק לשלש ברכות הללו שהבטיחו על הבנים, ועל הממון, ועל השם. (וזהו ואגדלה שמך, הריני מוסיף אות על שמך, שעד עכשיו שמך אברם מכאן ואלך אברהם, ואברהם עולה רמ''ח כנגד איבריו של אדם) : **ואברכך.** בממון: **והיה ברכה.** הברכות נתנות בידך, עד עכשיו היו בידי, ברכתי את אדם ואת נח ואותך, ומעכשיו אתה תברך את אשר תחפוץ. דבר אחר ואעשך לגוי גדול זהו שאומרים אלהי אברהם, ואברכך זהו שאומרים אלהי יצחק, ואגדלה שמך זהו שאומרים אלהי יעקב. יכול יהיו חותמין בכלן, תלמוד לומר והיה ברכה, בך חותמין ולא בהם: **מארצך.** והלא כבר יצא משם עם אביו ובא עד לחרן, אלא כך אמר לו התרחק עוד משם וצא מבית אביך: **אל הארץ אשר אראך.** לא גלה לו הארץ מיד, כדי לחבבה בעיניו, ולתת לו שכר על כל דבור ודבור. כיוצא בו (בראשית כב ב) את בנך את יחידך אשר אהבת את יצחק, כיוצא בו (כב ב) על אחד ההרים אשר אמר אליך, כיוצא בו (יונה ג ב) וקרא עליה את הקריאה אשר אנכי דובר אליך:
@3 **ונברכו בך כל משפחת האדמה.** יש אגדות רבות, וזהו פשוטו אדם אומר לבנו תהא כאברהם, וכן כל ונברכו בך שבמקרא, וזה מוכיח (בראשית מח כ) בך יברך ישראל לאמר ישימך אלהים כאפרים וכמנשה:
@5 **אשר עשו בחרן.** שהכניסן תחת כנפי השכינה, אברהם מגיר את האנשים, ושרה מגירת הנשים, ומעלה עליהם הכתוב כאלו עשאום. ופשוטו של מקרא עבדים ושפחות שקנו להם, כמו (שם לא א) עשה את כל הכבוד הזה, (במד' כד יח) וישראל עשה חיל, לשון קונה וכונס:
@6 **ויעבר אברם בארץ.** נכנס לתוכה: **עד מקום שכם.** להתפלל על בני יעקב כשיבאו להלחם בשכם: **אלון מורה.** הוא שכם, הראהו הר גריזים והר עיבל ששם קבלו ישראל שבועת התורה: **והכנעני אז בארץ.** היה הולך וכובש את ארץ ישראל מזרעו של שם, שבחלקו של שם נפלה כשחלק נח את הארץ לבניו, שנאמר (בראשית יד יח) ומלכי צדק מלך שלם, לפיכך (פסוק ז) ויאמר ה' אל אברם לזרעך אתן את הארץ הזאת, עתיד אני להחזירה לבניך שהם מזרעו של שם:
@7 **ויבן שם מזבח.** על בשורת הזרע ועל בשורת ארץ ישראל:
@8 **ויעתק משם.** אהלו: **מקדם לבית אל.** במזרחה של בית אל. נמצאת בית אל במערבו, והוא שנאמר בית אל מים: **אהלו.** אהלה כתיב, בתחלה נטה את אהל אשתו ואחר כך את שלו: **ויבן שם מזבח.** נתנבא שעתידין בניו להכשל שם על עון עכן והתפלל שם עליהם:
@9 **הלוך ונסוע.** לפרקים, יושב כאן חדש או יותר ונוסע משם ונוטה אהלו במקום אחר, וכל מסעיו הנגבה ללכת לדרומה של ארץ ישראל והוא לצד ירושלים שהיא בחלקו של יהודה, שנטלו בדרומה של ארץ ישראל הר המוריה שהיא נחלתו:
@10 **רעב בארץ.** באותה ארץ לבדה, לנסותו אם יהרהר אחר דבריו של הקדוש ברוך הוא שאמר לו ללכת אל ארץ כנען, ועכשיו משיאו לצאת ממנה:
@11 **הנה נא ידעתי.** מדרש אגדה עד עכשיו לא הכיר בה מתוך צניעות שבשניהם, ועכשיו על ידי מעשה הכיר בה. דבר אחר מנהג העולם שעל ידי טורח הדרך אדם מתבזה, וזאת עמדה ביפיה. ופשוטו של מקרא הנה נא הגיע השעה שיש לדאוג על יפיך, ידעתי זה ימים רבים כי יפת מראה את, ועכשיו אנו באים בין אנשים שחורים ומכוערים, אחיהם של כושים, ולא הרגלו באשה יפה. ודומה לו (בראשית יט ב) הנה נא אדני סורו נא:
@13 **למען ייטב לי בעבורך.** יתנו לי מתנות:
@14 **ויהי כבוא אברם מצרימה.** היה לו לומר כבואם מצרימה, אלא למד שהטמין אותה בתבה ועל ידי שתבעו את המכס פתחו וראו אותה:
@15 **ויהללו אותה אל פרעה.** הללוה ביניהם לומר הגונה זו למלך:
@16 **ולאברם היטיב.** פרעה **בעבורה.** [נתן לו מתנות]:
@17 **וינגע ה'** וגו' **.** במכת ראתן לקה, שהתשמיש קשה לו: **ואת ביתו.** כתרגומו ועל אנש ביתיה (ומדרשו לרבות כותליו ועמודיו וכליו) : **על דבר שרי.** על פי דבורה, אומרת למלאך הך והוא מכה:
@19 **קח ולך.** לא כאבימלך שאמר לו (כ טו) הנה ארצי לפניך, אלא אמר לו לך ואל תעמד, שהמצרים שטופי זמה הם, שנאמר (יחזקאל כג כ) וזרמת סוסים זרמתם:
@20 **ויצו עליו.** על אודותיו לשלחו ולשמרו: **וישלחו.** כתרגומו ואלויאו:
@21 **ויעל אברם** וגו' **הנגבה.** לבא לדרומה של ארץ ישראל כמו שאמור למעלה (פסוק ט) הלוך ונסוע הנגבה, להר המוריה, ומכל מקום כשהוא הולך ממצרים לארץ כנען מדרום לצפון הוא מהלך, שארץ מצרים בדרומה של ארץ ישראל, כמו שמוכיח במסעות ובגבולי הארץ:
@22 **כבד מאד.** טעון משאות:
@23 **וילך למסעיו.** כשחזר ממצרים לארץ כנען היה הולך ולן באכסניות שלן בהם בהליכתו למצרים. למדך דרך ארץ שלא ישנה אדם מאכסניא שלו. דבר אחר בחזרתו פרע הקפותיו: **מנגב.** ארץ מצרים בדרומה של ארץ כנען:
@24 **אשר עשה שם בראשנה ויקרא שם.** ואשר קרא שם אברם בשם ה'. וגם יש לומר ויקרא שם עכשיו בשם ה':
@25 **ההולך את אברם.** מי גרם שהיתה לו זאת, הליכתו עם אברם:
@26 **ולא נשא אתם.** לא היתה יכולה להספיק מרעה למקניהם, ולשון קצר הוא, וצריך להוסיף עליו, כמו ולא נשא אותם מרעה הארץ, לפיכך כתוב ולא נשא בלשון זכר:
@27 **ויהי ריב.** לפי שהיו רועים של לוט רשעים ומרעים בהמתם בשדות אחרים, ורועי אברם מוכיחים אותם על הגזל, והם אומרים נתנה הארץ לאברם, ולו אין יורש, ולוט יורשו, ואין זה גזל, והכתוב אומר והכנעני והפרזי אז ישב בארץ ולא זכה בה אברם עדיין:
@28 **אנשים אחים.** קרובים. ומדרש אגדה דומין בקלסתר פנים:
@29 **אם השמאל ואימנה.** בכל אשר תשב, לא אתרחק ממך ואעמוד לך למגן ולעזר. וסוף דבר הצרך לו שנאמר (יד יד) וישמע אברם כי נשבה אחיו וגו' : **ואימנה.** אימין את עצמי, כמו ואשמאילה אשמאיל את עצמי. ואם תאמר היה לו לנקד ואימינה, כך מצינו במקום אחר (ש''ב יד יט) אם אש להמין ואין נקוד להימין:
@30 **כי כלה משקה.** ארץ נחלי מים: **לפני שחת ה' את סדום ואת עמורה.** היה אותו מישור: **כגן ה'.** לאילנות: **כארץ מצרים.** לזרעים: **באכה צער.** עד צער. ומדרש אגדה דורשה לגנאי, על שהיו שטופי זמה בחר לו לוט בשכונתם במסכת הוריות (י ב) :
@31 **ככר.** מישור, כתרגומו: **מקדם.** נסע מאצל אברם והלך לו למערבו של אברם, נמצא נוסע ממזרח למערב. ומדרש אגדה הסיע עצמו מקדמונו של עולם אמר אי אפשי לא באברם ולא באלהיו:
@32 **ויאהל.** נטה אהלים לרועיו ולמקנהו עד סדום:
@33 **ואנשי סדום רעים.** ואף על פי כן לא נמנע לוט מלשכון עמהם. ורבותינו למדו מכאן (משלי י ז) שם רשעים ירקב: **רעים.** בגופם: **וחטאים.** בממונם: **לה' מאד.** יודעים רבונם ומתכונים למרוד בו:
@34 **אחרי הפרד לוט.** כל זמן שהרשע עמו היה הדבור פורש ממנו:
@36 **אשר אם יוכל איש.** כשם שאי אפשר לעפר להמנות, כך זרעך לא ימנה:
@38 **ממרא.** שם אדם:
@39 **אמרפל.** הוא נמרוד שאמר לאברהם פול לתוך כבשן האש: **מלך גוים.** מקום יש ששמו גוים, על שם שנתקבצו שמה מכמה אמות ומקומות והמליכו איש עליהם ושמו תדעל:
@40 **ברע.** רע לשמים ורע לבריות: **ברשע.** שנתעלה ברשעו: **שנאב.** שונא אביו שבשמים: **שמאבר.** שם אבר לעוף ולקפוץ ולמרוד בהקדוש ברוך הוא: **בלע.** שם העיר:
@41 **עמק השדים.** כך שמו, על שם שהיו בו שדות הרבה: **הוא ים המלח.** לאחר זמן נמשך הים לתוכו ונעשה ים המלח. ומדרש אגדה אומר שנתבקעו הצורים סביבותיו ונמשכו יאורים לתוכו:
@42 **שתים עשרה שנה עבדו.** חמשה מלכים הללו את כדרלעומר:
@43 **ובארבע עשרה שנה.** למרדן, **בא כדרלעומר' לפי שהוא היה בעל המעשה נכנס בעבי הקורה: והמלכים.** אלה שלשה מלכים: **הזוזים.** הם זמזמים:
@44 **בהררם.** בהר שלהם: **איל פארן.** כתרגומו מישור. ואומר אני שאין איל לשון מישור, אלא מישור של פארן איל שמו, ושל ממרא אלוני שמו, ושל ירדן ככר שמו, ושל שטים אבל שמו אבל השטים, וכן בעל גד בעל שמו, וכלם מתורגמין מישור, וכל אחד שמו עליו: **על המדבר.** אצל המדבר, כמו (במדבר ב כ) ועליו מטה מנשה:
@45 **עין משפט הוא קדש.** על שם העתיד, שעתידין משה ואהרן להשפט שם על עסקי אותו העין, והם מי מריבה. ואונקלוס תרגמו כפשוטו, מקום שהיו בני המדינה מתקבצים שם לכל משפט: **שדה העמלקי.** עדיין לא נלד עמלק ונקרא על שם העתיד: **בחצצון תמר.** הוא עין גדי, מקרא מלא (דה''י ב' כ ב) ביהושפט:
@47 **ארבעה מלכים את החמשה.** ואף על פי כן נצחו המועטים, להודיעך שגבורים היו, ואף על פי כן לא נמנע אברהם מלרדוף אחריהם:
@48 **בארת בארת חמר.** בארות הרבה היו שם שנוטלין משם אדמה לטיט של בנין. ומדרש אגדה שהיה הטיט מגבל בהם, ונעשה נס למלך סדום שיצא משם, לפי שהיו באמות מקצתן שלא היו מאמינין שנצל אברהם מאור כשדים מכבשן האש, וכיון שיצא זה מן החמר האמינו באברהם למפרע: **הרה נסו.** להר נסו. הרה כמו להר, כל תבה שצריכה למ''ד בתחלתה הטיל לה ה''א בסופה. ויש חלוק בין הרה לההרה שה''א שבסוף התבה עומדת במקום למ''ד שבראשה, אבל אינה עומדת במקום למ''ד ונקודה פת''ח תחתיה, והרי הרה כמו להר, או כמו אל הר, ואינו מפרש לאיזה הר, אלא שכל אחד נס כאשר מצא הר תחלה, וכשהוא נותן ה''א בראשה לכתוב ההרה או המדברה, פתרונו כמו אל ההר או כמו לההר, ומשמע לאותו הר הידוע ומפורש בפרשה:
@50 **והוא ישב בסדום.** מי גרם לו זאת, ישיבתו בסדום:
@51 **ויבא הפליט.** [מדרשו] לפי פשוטו זה עוג שפלט מן המלחמה, והוא שכתוב (דברים ג יא) כי רק עוג נשאר מיתר הרפאים, וזהו נשאר שלא הרגוהו אמרפל וחבריו כשהכו את הרפאים בעשתרות קרנים, תנחומא (חוקת כה) . ומדרש בראשית רבה (מב ח) זה עוג שפלט מדור המבול, וזהו מיתר הרפאים שנאמר (ו ד) הנפלים היו בארץ וגו' ומתכון שיהרג אברהם וישא את שרה: **העברי.** שבא מעבר הנהר: **בעלי ברית אברם.** שכרתו עמו ברית (דבר אחר שהשיאו לו עצה על המילה כמו שמפורש במקום אחר) :
@52 **וירק.** כתרגומו וזרז, וכן (ויקרא כו לג) והריקתי אחריכם חרב, אזדיין בחרבי עליכם, וכן (שמות טו ט) אריק חרבי, וכן (תהלים לה ג) והרק חנית וסגר: **חניכיו.** חנכו כתיב זה אליעזר שחנכו למצוות והוא לשון התחלת כניסת האדם או כלי לאמנות שהוא עתיד לעמוד בה, וכן (משלי כב ו) חנך לנער, (במדבר ז יא) חנכת המזבח, (תהלים ל א) חנכת הבית ובלע''ז קורין לו איניציי''ר : **שמנה עשר ושלש מאות.** רבותינו אמרו אליעזר לבדו היה, והוא מנין גימטריא של שמו: **עד דן.** שם תשש כחו, שראה שעתידין בניו להעמיד שם עגל:
@53 **ויחלק עליהם.** לפי פשוטו, סרס המקרא, ויחלק הוא ועבדיו עליהם לילה כדרך הרודפים שמתפלגים אחר הנרדפים כשבורחים זה לכאן וזה לכאן: **לילה.** כלומר אחר שחשכה לא נמנעו מלרדפם. ומדרש אגדה שנחלק הלילה ובחציו הראשון נעשה לו נס, וחציו השני נשמר ובא לו לחצות לילה של מצרים: **עד חובה.** אין מקום ששמו חובה, אלא דן קורא חובה על שם עבודה זרה שעתידה להיות שם:
@55 **עמק שוה.** כך שמו כתרגומו למישר מפנא, פנוי מאילנות ומכל מכשול: **עמק המלך.** בית ריסא דמלכא, בית ריס אחד שהוא שלשים קנים, שהיה מיוחד למלך לשחק שם. ומדרש אגדה עמק שהשוו שם כל האמות והמליכו את אברהם עליהם לנשיא אלהים ולקצין:
@56 **ומלכי צדק.** מדרש אגדה הוא שם בן נח: **לחם ויין.** כך עושים ליגיעי מלחמה, והראה לו שאין בלבו עליו על שהרג את בניו. ומדרש אגדה רמז לו על המנחות ועל הנסכים שיקריבו שם בניו:
@57 **קנה שמים וארץ.** כמו (תהלים קלד ג) עשה שמים וארץ, על ידי עשיתן קנאן להיות שלו:
@58 **אשר מגן.** אשר הסגיר, וכן (הושע יא ח) אמגנך ישראל: **ויתן לו.** אברם, מעשר מכל אשר לו לפי שהיה כהן:
@59 **תן לי הנפש.** מן השבי שלי שהצלת, החזר לי הגופים לבדם:
@60 **הרימתי ידי.** לשון שבועה, מרים אני את ידי לאל עליון וכן (בראשית כב טז) בי נשבעתי, נשבע אני, וכן (שם כג יג) נתתי כסף השדה קח ממני, נותן אני לך כסף השדה וקחהו ממני:
@61 **אם מחוט ועד שרוך נעל.** אעכב לעצמי מן השבי: **ואם אקח מכל אשר לך.** ואם תאמר לתת לי שכר מבית גנזיך, לא אקח: **ולא תאמר אני העשרתי את אברם.** שהקדוש ברוך הוא הבטיחני לעשרני, שנאמר לעיל (יב ב) ואברכך וגו' :
@62 **הנערים.** עבדי אשר הלכו אתי, ועוד ענר אשכל וממרא וגו' . ואף על פי שעבדי נכנסו למלחמה, שנאמר לעיל (פסוק טו) הוא ועבדיו ויכם, וענר וחבריו ישבו על הכלים לשמר, אפלו הכי הם יקחו חלקם. וממנו למד דוד שאמר (ש''א ל כד) כחלק הירד למלחמה וכחלק הישב על הכלים יחדו יחלקו. לכך נאמר (שם פסוק כה) ויהי מהיום ההוא ומעלה וישמה לחק ולמשפט, ולא נאמר והלאה לפי שכבר נתן החוק בימי אברהם:
@63 **אחר הדברים האלה.** כל מקום שנאמר אחר סמוך, אחרי מפלג. אחר שנעשה לו נס זה שהרג את המלכים והיה דואג ואומר שמא קבלתי שכר על כל צדקתי, לכך אמר לו המקום אל תירא אברם אנכי מגן לך מן הענש שלא תענש על כל אותן נפשות שהרגת, ומה שאתה דואג על קבול שכרך, שכרך הרבה מאד:
@64 **הולך ערירי.** מנחם בן סרוק פרשו לשון יורש, וחבר לו (מלאכי ב יב) ער וענה, ערירי בלא יורש, כאשר תאמר (איוב לא יב) ובכל תבואתי תשרש, תעקר שרשיה, כך לשון ערירי חסר בנים, ובלע''ז דישאנפנטי''ף . ולי נראה ער וענה מגזרת (שיר השירים ה ב) ולבי ער, וערירי לשון חרבן, וכן (תהל' קלז ז) ערו ערו, וכן (חבק' ג יג) ערות יסוד, וכן (ירמיה נא נח) ערער תתערער, וכן (צפניה ב יד) כי ארזה ערה: **ובן משק ביתי.** כתרגומו, שכל ביתי נזון על פיו, כמו (בראשית מא מ) ועל פיך ישק, אפטורפס שלי, ואלו היה לי בן היה בני ממנה על שלי: **דמשק.** לפי התרגום מדמשק היה, ולפי מדרש אגדה שרדף המלכים עד דמשק. ובתלמוד דרשו נוטריקון דולה ומשקה מתורת רבו לאחרים:
@65 **הן לי לא נתת זרע.** ומה תועלת בכל אשר תתן לי:
@67 **ויוצא אתו החוצה.** לפי פשוטו הוציאו מאהלו לחוץ לראות הכוכבים, ולפי מדרשו אמר לו צא מאצטגנינות שלך שראית במזלות שאינך עתיד להעמיד בן, אברם אין לו בן, אבל אברהם יש לו בן. וכן שרי לא תלד, אבל שרה תלד, אני קורא לכם שם אחר וישתנה המזל. דבר אחר הוציאו מחללו של עולם והגביהו למעלה מן הכוכבים, וזהו לשון הבטה מלמעלה למטה:
@68 **והאמין בה'.** לא שאל לו אות על זאת, אבל על ירשת הארץ שאל לו אות ואמר לו במה אדע: **ויחשבה לו צדקה.** הקדוש ברוך הוא חשבה לאברם לזכות ולצדקה על האמונה שהאמין בו. דבר אחר במה אדע, לא שאל לו אות אלא אמר לפניו הודיעני באיזה זכות יתקימו בה, אמר לו הקדוש ברוך הוא בזכות הקרבנות:
@71 **עגלה משלשת.** שלשה עגלים, רמז לשלשה פרים פר יום הכפורים, ופר העלם דבר של צבור, ועגלה ערופה: **ועז משלשת.** רמז לשעיר הנעשה בפנים, ושעירי מוספין של מועד, ושעיר חטאת יחיד: **ואיל משלש.** אשם ודאי, ואשם תלוי, וכבשה של חטאת יחיד: **ותור וגוזל.** תור ובן יונה:
@72 **ויבתר אתם.** חלק כל אחד לשני חלקים, ואין המקרא יוצא מידי פשוטו לפי שהיה כורת עמו ברית לשמור הבטחתו להוריש לבניו את הארץ, כדכתיב (פסוק יח) ביום ההוא כרת ה' את אברם ברית לאמר וגו' , ודרך כורתי ברית לחלק בהמה ולעבר בין בתריה, כמה שנאמר להלן (ירמיה לד יט) העוברים בין בתרי העגל, אף כאן תנור עשן ולפיד אש אשר עבר בין הגזרים הוא שלוחו של שכינה שהוא אש: **ואת הצפור לא בתר.** לפי שהאמות נמשלו לפרים ואילים ושעירים, שנאמר (תהלים כב יג) סבבוני פרים רבים וגו' , ואומר (דניאל ח כ) והאיל אשר ראית בעל הקרנים מלכי מדי ופרס. ואומר (שם כא) והצפיר השעיר מלך יון, וישראל נמשלו לבני יונה שנאמר (שה''ש ב יד) יונתי בחגוי הסלע, לפיכך בתר הבהמות רמז על האמות שיהיו כלין והולכין, ואת הצפור לא בתר רמז שיהיו ישראל קימין לעולם:
@73 **העיט.** הוא עוף, ועל שם שהוא עט ושואף הנבלות (איוב ט כו) לטוש עלי אכל, כמו (שמואל א' טו יט) ותעט אל השלל: **על הפגרים.** על הבתרים (הפגרים מתרגמינן פגליא, אלא מתוך שהרגלו לתרגם (פסוק י) איש בתרו, ויהב פלגיא, נתחלף להם תבת פגליא לפלגיא, ותרגמו הפגרים פלגיא, וכל המתרגם כן טועה, לפי שאין להקיש בתרים לפגרים, שבתרים תרגומו פלגיא, ופגרים תרגומו פגליא לשון פגול, כמו (ויקרא יט ז) פגול הוא לשון פגר) : **וישב.** לשון נשיבה והפרחה, כמו (תהל' קמז יח) ישב רוחו, רמז שיבא דוד בן ישי לכלותם, ואין מניחין אותו מן השמים עד שיבא מלך המשיח:
@74 **והנה אימה** וגו' **.** רמז לצרות וחשך של גליות:
@75 **כי גר יהיה זרעך.** משנלד יצחק עד שיצאו ישראל ממצרים ארבע מאות שנה. כיצד, יצחק בן ששים שנה כשנלד יעקב. ויעקב כשירד למצרים אמר (להלן מז ט) ימי שני מגורי שלשים ומאת שנה, הרי מאה ותשעים, ובמצרים היו מאתים ועשר כמנין רדו, הרי ארבע מאות שנה. ואם תאמר במצרים היו ארבע מאות, הרי קהת מיורדי מצרים היה, צא וחשוב שנותיו של קהת, ושל עמרם, ושמונים של משה שהיה כשיצאו ישראל ממצרים, אין אתה מוצא אלא שלש מאות וחמשים, ואתה צריך להוציא מהן כל השנים שחי קהת אחר לידת עמרם, ושחי עמרם אחר לידת משה: **בארץ לא להם.** לא נאמר בארץ מצרים אלא בארץ לא להם, ומשנלד יצחק (להלן כא לד) ויגר אברהם וגו' , וביצחק (שם כו ג) גור בארץ הזאת, (תהלים קה כג) ויעקב גר בארץ חם, (בראשית מז ד) לגור בארץ באנו:
@76 **וגם את הגוי.** וגם לרבות ארבע מלכיות, שאף הם כלים על ששעבדו את ישראל: **דן אנכי.** בעשר מכות: **ברכוש גדול.** בממון גדול, כמו שנאמר (שמות יב לו) וינצלו את מצרים:
@77 **ואתה תבוא.** ולא תראה כל אלה: **אל אבתיך.** אביו עובד עבודה זרה והוא מבשרו שיבא אליו, אלא למדך שעשה תרח תשובה: **תקבר בשיבה טובה.** בשרו שיעשה ישמעאל תשובה בימיו ולא יצא עשו לתרבות רעה בימיו, ולפיכך מת חמש שנים קודם זמנו ובו ביום מרד עשו:
@78 **ודור רביעי.** לאחר שיגלו למצרים יהיו שם שלשה דורות, והרביעי ישובו לארץ הזאת, לפי שבארץ כנען היה מדבר עמו וכרת ברית זו, כדכתיב (פסוק ז) לתת לך את הארץ הזאת לרשתה, וכן היה. יעקב ירד למצרים. צא וחשוב דורותיו יהודה, פרץ, חצרון, וכלב בן חצרון מבאי הארץ היה: **כי לא שלם עון האמורי.** להיות משתלח מארצו עד אותו זמן, שאין הקדוש ברוך הוא נפרע מאמה עד שתתמלא סאתה, שנאמר (ישעיה כז ח) בסאסאה בשלחה תריבנה:
@79 **ויהי השמש באה.** כמו ויהי הם מריקים שקיהם (בראשית מב לה) , ויהי הם קוברים איש, כלומר ויהי דבר זה (מ''ב יג כא) : **השמש באה.** שקעה: **ועלטה היה.** חשך היום: **והנה תנור עשן** וגו' **.** רמז לו שיפלו המלכיות בגיהנם. באה טעמו למעלה, לכך הוא מבואר שבאה כבר, ואם היה טעמו למטה באל''ף היה מבואר כשהיא שוקעת. ואי אפשר לומר כן, שהרי כבר כתיב ויהי השמש לבא, והעברת תנור עשן לאחר מכאן היתה נמצא שכבר שקעה. וזה חלוק בכל תבה לשון נקבה שיסודה שתי אותיות, כמו בא, קם, שב, כשהטעם למעלה, לשון עבר הוא, כגון זה, וכגון (להלן כט ט) ורחל באה, (שם לז ז) קמה אלמתי, (רות א טו) הנה שבה יבמתך, וכשהטעם למטה הוא לשון הוה, דבר שנעשה עכשיו והולך, כמו (להלן כט ו) באה עם הצאן, (אסתר ב יד) בערב היא באה ובבקר היא שבה:
@80 **לזרעך נתתי.** אמירתו של הקדוש ברוך הוא כאלו היא עשויה: **הנהר הגדול נהר פרת.** לפי שהוא דבוק לארץ ישראל קראהו גדול אף על פי שהוא מאוחר בארבעה נהרות היוצאים מעדן, שנאמר והנהר הרביעי הוא פרת. משל הדיוט עבד מלך מלך, הדבק לשחור וישתחוו לך:
@81 **את הקיני.** עשר אמות יש כאן ולא נתן להם אלא שבעה גוים, והשלשה אדום ומואב ועמון, והם קיני קניזי וקדמוני עתידים להיות ירשה לעתיד, שנאמר (ישעיה יא יד) אדום ומואב משלוח ידם ובני עמון משמעתם:
@82 **ואת הרפאים.** ארץ עוג, שנאמר בה (דברים ג יג) ההוא יקרא ארץ רפאים:
@84 **שפחה מצרית.** בת פרעה היתה, כשראה נסים שנעשו לשרה אמר מוטב שתהא בתי שפחה בבית זה ולא גבירה בבית אחר:
@85 **אולי אבנה ממנה.** למד על מי שאין לו בנים שאינו בנוי אלא הרוס: **אבנה ממנה.** בזכות שאכניס צרתי לתוך ביתי: **לקול שרי.** לרוח הקודש שבה:
@86 **ותקח שרי.** לקחתה בדברים אשריך שזכית לדבק בגוף קדוש כזה: **מקץ עשר שנים.** מועד הקבוע לאשה ששהתה עשר שנים ולא ילדה לבעלה חיב לשא אחרת: **לשבת אברם** וגו' **.** מגיד שאין ישיבת חוצה לארץ עולה לו מן המנין, לפי שלא נאמר לו (לעיל יב ב) ואעשך לגוי גדול, עד שיבא לארץ ישראל:
@87 **ויבא אל הגר ותהר.** מביאה ראשונה: **ותקל גברתה בעיניה.** אמרה שרי זו אין סתרה כגלויה, מראה עצמה כאלו היא צדקת ואינה צדקת, שלא זכתה להריון כל השנים הללו, ואני נתעברתי מביאה ראשונה:
@88 **חמסי עליך.** חמס העשוי לי, עליך אני מטילה הענש, כשהתפללת להקדוש ברוך הוא מה תתן לי ואנכי הולך ערירי, לא התפללת אלא עליך, והיה לך להתפלל על שנינו והייתי אני נפקדת עמך. ועוד, דבריך אתה חומס ממני שאתה שומע בזיוני ושותק: **אנכי נתתי שפחתי** וגו' **ביני וביניך.** כל ביני ובינך שבמקרא חסר, וזה מלא, קרי ביה וביניך שהכניסה עין הרע בעבורה של הגר והפילה עברה, הוא שהמלאך אומר להגר הנך הרה, והלא כבר הרתה והוא מבשר לה שתהר, אלא מלמד שהפילה הריון הראשון:
@89 **ותענה שרי.** היתה משעבדת בה בקושי:
@91 **אי מזה באת.** מהיכן באת. יודע היה, אלא לתן לה פתח לכנס עמה בדברים. ולשון אי מזה, איה המקום שתאמר עליו מזה אני באה:
@92 **ויאמר לה מלאך ה'** וגו' **.** על כל אמירה היה שלוח לה מלאך אחר, לכך נאמר מלאך בכל אמירה ואמירה:
@94 **הנך הרה.** כשתשובי תהרי, כמו (שופטים יג ז) הנך הרה, דאשת מנוח: **וילדת בן.** כמו ויולדת, ודומה לו (ירמיה כב כג) ישבת בלבנון מקננת בארזים: **וקראת שמו.** צווי הוא, כמו שאומר לזכר (יז יט) וקראת את שמו יצחק:
@95 **פרא אדם.** אוהב מדברות לצוד חיות, כמו שכתוב (כא כ. כא) ויהי רבה קשת וישב במדבר פארן: **ידו בכל.** לסטים: **ויד כל בו.** הכל שונאין אותו ומתגרין בו: **ועל פני כל אחיו ישכן.** שיהיה זרעו גדול:
@96 **אתה אל ראי.** נקוד חטף קמ''ץ מפני שהוא שם דבר, אלוה הראיה, שרואה בעלבון של עלובין: **הגם הלם.** לשון תימה, וכי סבורה הייתי שאף הלום במדברות ראיתי שלוחו של מקום אחרי רואי אותם בביתו של אברהם, ששם הייתי רגילה לראות מלאכים. ותדע שהיתה רגילה לראותם שהרי מנוח ראה את המלאך פעם אחת ואמר (שופטים יג כב) מות נמות, וזו ראתה ארבעה פעמים זה אחר זה ולא חרדה:
@97 **באר לחי ראי.** כתרגומו בירא דמלאך קיימאאתחזי עלה:
@98 **ויקרא אברם שם** וגו' **.** אף על פי שלא שמע אברם דברי המלאך שאמר (פסוק יא) וקראת שמו ישמעאל, שרתה רוח הקדש עליו וקראו ישמעאל:
@99 **ואברם בן שמנים שנה** וגו' **.** לשבחו של ישמעאל נכתב, להודיע שהיה בן שלש עשרה שנה כשנמול ולא עכב:
@100 **אני אל שדי.** אני הוא שיש די באלהותי לכל בריה, לפיכך התהלך לפני ואהיה לך לאלוה ולפטרון, וכן כל מקום שהוא במקרא פרושו די יש לו, והכל לפי הענין: **התהלך לפני.** כתרגומו פלח קדמי, הדבק בעבודתי: **והיה תמים.** אף זה צווי אחר צווי, היה שלם בכל נסיונותי. ולפי מדרשו התהלך לפני במצות מילה, ובדבר הזה תהיה תמים, שכל זמן שהערלה בך אתה בעל מום לפני. דבר אחר והיה תמים, עכשיו אתה חסר חמשה אברים שתי עינים, שתי אזנים, וראש הגויה שאוסיף לך אות על שמך ויהיו מנין אותיותיך מאתים ארבעים ושמונה כמנין אבריך:
@101 **ואתנה בריתי.** ברית של אהבה וברית הארץ להורישה לך על ידי מצוה זו:
@102 **ויפל אברם על פניו.** ממורא השכינה, שעד שלא מל לא היה בו כח לעמוד ורוח הקדש נצבת עליו, וזהו שנאמר בבלעם (במדבר כד ד) נפל וגלוי עינים. בברייתא דרבי אליעזר מצאתי כן:
@104 **כי אב המון גוים.** לשון נוטריקון של שמו. ורי''ש שהיתה בו בתחלה, שלא היה אב אלא לארם שהוא מקומו ועכשיו אב לכל העולם, לא זזה ממקומה, שאף יו''ד של שרי נתרעמה על השכינה עד שנתוספה ליהושע, שנאמר (במדבר יג טז) ויקרא משה להושע בן נון יהושע:
@105 **ונתתיך לגוים.** ישראל ואדום, שהרי ישמעאל כבר היה לו ולא היה מבשרו עליו:
@106 **והקמתי את בריתי.** ומה היא הברית, להיות לך לאלהים:
@107 **לאחזת עולם.** ושם אהיה להם לאלהים, אבל הדר בחוצה לארץ דומה כמי שאין לו אלוה:
@108 **ואתה.** וא''ו זו מוסיף על ענין ראשון אני הנה בריתי אתך, ואתה הוי זהיר לשמרו, ומה היא שמירתו, (פסוק י) זאת בריתי אשר תשמרו המול לכם וגו' :
@109 **ביני וביניכם** וגו' **.** אותם של עכשיו: **ובין זרעך אחריך.** העתידין להולד: **המול.** כמו להמול כמו שאתה אומר עשות, כמו לעשות:
@110 **ונמלתם.** כמו ומלתם והנו''ן בו יתרה ליסוד הנופל בו לפרקים, כגון נ' של נושך ונ' של נושא. ונמלתם, כמו ונשאתם, אבל ימול לשון יפעל כמו יעשה, יאכל:
@111 **יליד בית.** שילדתו השפחה בבית: **ומקנת כסף.** שקנאו משנלד:
@112 **המול ימול יליד ביתך.** כאן כפל עליו ולא אמר לשמונה ימים, ללמדך שיש יליד בית נמול לאחר שמנה ימים, כמו שמפורש במסכת שבת (דף קלח ב) :
@113 **וערל זכר.** כאן למד שהמילה באותו מקום שהוא נכר בין זכר לנקבה: **אשר לא ימול.** משיגיע לכלל ענשין ונכרתה, אבל אביו אין ענוש עליו כרת אבל עובר בעשה: **ונכרתה הנפש.** הולך ערירי ומת קודם זמנו:
@114 **לא תקרא את שמה שרי.** דמשמע שרי לי ולא לאחרים כי שרה סתם שמה, שתהא שרה על כל:
@115 **וברכתי אתה.** ומה היא הברכה, שחזרה לנערותה, שנאמר (לקמן יח יב) אחרי בלתי היתה לי עדנה: **וברכתיה.** בהנקת שדים, כשנצרכה לכך ביום משתה של יצחק, שהיו מרננים עליהם שהביאו אסופי מן השוק ואומרים בננו הוא, והביאה כל אחת בנה עמה ומניקתה לא הביאה, והיא היניקה את כלם, הוא שנאמר (כא ז) היניקה בנים שרה. בראשית רבה (נג ט) רמזו במקצת:
@116 **ויפל אברהם על פניו ויצחק.** זה תירגם אנקלוס וחדי, לשון שמחה, ושל שרה לשון מחוך. למדת שאברהם האמין ושמח, ושרה לא האמינה ולגלגה. וזהו שהקפיד הקדוש ברוך הוא על שרה ולא הקפיד על אברהם: **הלבן.** יש תמיהות שהן קימות כמו (ש''א ב כז) הנגלה נגליתי, (ש''ב טו כז) הראה אתה, אף זו היא קימת, וכך אמר בלבו הנעשה חסד זה לאחר מה שהקדוש ברוך הוא עושה לי: **ואם שרה הבת תשעים שנה.** היתה כדאי לילד. ואף על פי שדורות הראשונים היו מולידין בני חמש מאות שנה, בימי אברהם נתמעטו השנים כבר ובא תשות כח לעולם, וצא ולמד מעשרה דורות שמנח ועד אברהם שמיהרו תולדותיהן בני ששים ובני שבעים:
@117 **לו ישמעאל יחיה.** הלואי שיחיה ישמעאל, איני כדאי לקבל מתן שכר כזה: **יחיה לפניך.** יחיה ביראתך, כמו (פסוק א) התהלך לפני, פלח קדמי:
@118 **אבל.** לשון אמתת דברים, וכן (לקמן מב כא) אבל אשמים אנחנו, (מ''ב ד יד) אבל בן אין לה: **וקראת את שמו יצחק.** על שם הצחוק. ויש אומרים על שם י' נסיונות, וצ' שנה של שרה, וח' ימים שנמול, וק' שנה של אברהם. והקימתי את בריתי למה נאמר, והרי כבר כתיב (פסוק ט) ואתה את בריתי תשמור אתה וזרעך וגו' אלא לפי שאומר (פסוק ז) והקמתי וגו' , יכול בני ישמעאל ובני קטורה בכלל הקיום, תלמוד לומר והקמותי את בריתי אתו, ולא עם אחרים. ואת בריתי אקים את יצחק, למה נאמר, [אלא למד שהיה קדוש מבטן]. דבר אחר אמר ר' אבא מכאן למד קל וחומר בן הגבירה מבן האמה, כתיב (פסוק כ) כי הנה ברכתי אותו והפריתי אותו והרביתי אותו, זה ישמעאל וקל וחמר ואת בריתי אקים את יצחק: **את בריתי.** ברית המילה תהא מסורה לזרעו של יצחק:
@119 **שנים עשר נשיאם.** כעננים יכלו, כמו (משלי כה יד) נשיאים ורוח:
@121 **מעל אברהם.** לשון נקיה הוא כלפי שכינה, ולמדנו שהצדיקים מרכבתו של מקום:
@122 **בעצם היום.** בו ביום שנצטוה, ביום ולא בלילה, לא נתיירא לא מן הגוים ולא מן הלצנים, ושלא יהיו אויביו ובני דורו אומרים אלו ראינוהו לא הנחנוהו למול ולקים מצותו של מקום: **וימל.** לשון ויפעל:
@123 **בהמלו.** בהפעלו, כמו (ב ד) בהבראם:
@124 **בהמלו את בשר ערלתו.** באברהם לא נאמר את, לפי שלא היה חסר אלא חתוך בשר, שכבר נתמעך על ידי תשמיש, אבל ישמעאל שהיה ילד הוזקק לחתוך ערלה ולפרוע המילה, לכך נאמר בו את:
@125 **בעצם היום הזה.** שמלאו לאברהם תשעים ותשע שנה ולישמעאל שלש עשרה שנים נמול אברהם וישמעאל בנו:

@1 **ויאמר ה' אל אברם וגו'**. טעם שדבר אליו ה' קודם הראות לו, מה שלא עשה כן בכל הנבראים, ב' טעמים בדבר, או להיות שהוא עליו השלום נשתדל בהכרת בוראו מה שלא עשה אדם זולתו ובן חמש שנים הכיר את בוראו מעצמו בהתחכמותו (נדרים לב.), לזה לא הוצרך להגלות אליו אלא אמר אליו דברותיו וכבר הוכר אצלו המדבר. או אפשר, כי להיותו אדם ראשון בקדושה, אשר בעשרה דורות שקדמוהו לא היה אדם שהכיר אלהותו ודבר אתו אלהים, לזה נהג ה' עמו בסדר זה שלא הראה שכינתו אליו עד שבחן אותו אם מקיים גזרותיו, ולאחר שקיים דבריו והלך לו מארצו וכו' אז נגלה אליו דכתיב (פסוק ז) וירא ה' אל אברם, מה שאין כן שאר הנבראים שכבר קדמה ונשתקעה האמונה בלבם מאברהם והושרשו בקדושה היה נגלה להם תחלה. וצא ולמד מאבות ומשה בסנה. ודרך זה מסכים לדברי רז''ל (ב''ר פל''ט) שהעמידו פסוק (תהלים מה) שמעי בת וראי וגו' באברהם אבינו, בתחלה שמעי והוא אומרו **ויאמר ה' אל** וגו', ואחר כך נגלה אליו וירא וגו', והוא אומרו וראי. ולא היו שניהם שמיעה וראיה כאחת אלא בהפסק ביניהם. ולזה לא אמר הכתוב שמעי וראי בת או בת שמעי וראי והפסיק בין שמעי לוראי:
@1 **לך לך מארצך וגו'**. אחר שאמר מארצך אין מקום לומר ממולדתך כי בצאתו מארצו הנה הוא יוצא גם ממולדתו:
@1 **אכן** הטעם הוא להיות כי בערך צער הפרידה קטן הוא צער פרידתו מארצו מפרידת מולדתו ופרידתו ממולדתו מפרידתו מבית אביו לזה סדר ההדרגות ממטה למעלה. וליטול שכר על כל פרט ופרט, כדרך אומרו (לקמן כב כ) את בנך וגו' כי ה' ישתדל להטיב ב''ה לאוהביו:
@1 **עוד** ירצה לומר שילך לו מארצו אך לא יהיה כסדר יציאתו מאור כשדים שיוליך עמו מולדתו ובית אביו אלא הוא לבדו יעזוב ארצו ויפרד גם ממולדתו ואפילו מבית אביו. אך אברהם לא הבין זה בדברי ה' ולקח עמו לוט. או אפשר שהבין כן אלא שלוט דבק בו כאומרו (לק' ד') וילך אתו לוט דבק בו. והגם שאמר אחר כך (לק' ה') ויקח אברם וגו' ואת לוט וגו' פירוש שלא דחפו, עד שימצא המצאה שלא יכלימהו. ולזה תמצא כי כשמצא סיבה קטנה שרבו הרועים תיכף אמר אליו (לק' יג, ט) הפרד וגו' אם הימין וגו', והדבר הוא כמעט זר שיאמר אליו כדברים האלה בכל כך הרחקה, אלא לצד שהיה חושב מחשבות להפרידו כדבר ה' לזה תכף במוצאו סיבה דחפו בב' ידים. וראיתי לחזק פירוש זה גם כן ממה שאמר הכתוב (לקמן יג, יד) וה' אמר אל אברם אחרי הפרד לוט מעמו שא נא עיניך מאמר זה יוכיח כי יושב ומצפה היה ה' מתי יפרד לוט, להראותו את הארץ שאמר לו בתחלת דבר אליו, אשר אראך, ולא הראהו עד עתה שנפרד לוט, והוא מאמר ראשון לך לך מארצך וממולדתך ומבית אביך אז אראך:
@1 **עוד** יכוון לומר על זה הדרך **לך לך** לתועלתך והגם שאין הטובה מסובבת מהשתדלות כאומ' (תהלים עה) לא ממוצא וממערב וגו' הרים וגו' ודרשו ז''ל (במד''ר פכ''ה) וזה לשונם כל הרים שבמקרא כמשמעה חוץ מזו שהיא לשון הרמה ע''כ. אף על פי כן יש טעם בדבר לצד שינוי מקום, והוא אומרו **מארצך**, ואמרו ז''ל (חולין צה:) ג' דברים אף על פי שאין נחש יש סימן והם בית תינוק וכו', ואמרו עוד (ב''מ עה:) מאן דביש ליה בהאי מתא ולא אזיל למתא אחריתא צועק לפני ה' ואינו נענה:
@1 **וממולדתך**. על דרך אומרם ז''ל (רמב''ם דעות ו') לעולם ידור אדם בשכונת אריה ולא בעיר עם רשעים ע''כ:
@1 **אל הארץ אשר אראך**. פירוש שלא הודיעו, לראות אם ימהר לעשות דבר מלך שלטון מבלי דעת המקום, וזה נסיון מהנסיונות. עוד רמזו שיראנה לו כולה דכתיב (לקמן י''ג י''ד) שא נא עיניך וראה צפונה ונגבה וגו' ונתן לו כח הראיה לראות כולה:
@1 **עוד** יתבאר על דרך מה שאמרו בספרי בפסוק (במדבר לה) אשר אני שוכן בתוכה אשר אני שוכן בתוך בני ישראל אין שכינה שורה אלא בתוך בני ישראל ובעודן בארץ ע''כ, והוא שאמר ה' לאברהם **אל הארץ אשר אראך** פירוש ראויה לך ואתה ראוי לה. ושיעור התיבה הוא אראה אותך לה ואראה אותה לך כי זה בלא זה אינם ראוים להשראת שכינה ולרוב ההצלחות:
@2 **ואעשך לגוי גדול וגו'**. להיות שצוה לו ג' קבע לו כנגדם ג', **ואעשך** וגו' כנגד לך לך מארצך, **ואברכך ואגדלה שמך** כנגד וממולדתך, **והיה ברכה** כנגד ומבית אביך. שתמצא כי בהיות האדם בארצו תוך משפחתו ובית אביו ישנו בג' דברים, הא' שיש לו הרבה מכירים וריעים ואוהבים. ב' שבני משפחתו תפארהו וכבוד והדר תעטרהו כדרך כל משפחה לבני משפחתם. ג' שיהיה ניזון ומתפרנם ומתרחם מבית אביו לצרכיו, וכשיוצא מארצו וכו' חסר לכולן, ולזה אמר אליו ה' כנגד מארצך אני אעשה לך הרבה אוהבים ממך מיוצאי חלציך. וכנגד חסרון התועלת של בני המשפחה כנזכר ואברכך ואגדלה שמך, וכנגד חסרון המועיל מבית אביך והיה ברכה:
@3 **ואברכה מברכיך וגו'**. ברכה זו כנגד מה שהעלים ממנו הארץ ולא הודיעו קודם לצאתו, ונסיון זה גדול הוא שיצא מארצו אל השדה מבלי דעת אן יפנה והוא לא הרהר לזה הבטיחו כי לא יפחד מדבר כי הוא יברך וכו' ובמקום אשר יחנה שם יצו ה' אתו את הברכה ובזה כל מקום אשר ידרוך כף רגלו הצלחתו ומעלתו עמו:
@3 **ויש** לשאול למה שינה לשונו בענין הברכה אמר ואברכה מברכיך הקדים ברכתו לברכתם ובקללה הקדים קללתם לקללתו. הטעם הוא כי המברך יקדים ה' לברכו קודם שיברך לאברהם מה שאין כן המקללו לא יקדים ה' לאור אותו. והטעם הוא כי יחפוץ ה' להפחיד לבל יזלזל אדם בכבודו של אברהם. וזולת זה אם יקדים ה' לקלל מי שהוא עתיד לקלל לא יורגש הדבר כי הוא זה סיבה ויכשלו בדבר בני אדם גם בני איש. אבל בערך הברכה אין מכשול. ואם לצד ההטבה, הנה מבורכים בו כל המשפחות. גם טעם הקדמת ברכת המברכים כדי שתתקיים ברכתם לאברהם:
@3 **עוד** יכוין לומר במה שנדקדק למה המברכים הזכירם בלשון רבים והמקללים הזכירם בלשון יחיד:
@3 **אכן** יתבאר על דרך אומרם במסכת מועד קטן (ט:) שאמרו רבנן לבנו של רשב''י תזרע ולא תחצד וכו' ונתכוונו בזה לברכה. והגם שהוציאו דבריהם בלשון קללה הכל הולך אחר הכוונה הרי שברכוהו בנוסח קללה. וכנגד זו אמר ה' **ואברכה מברכך** וגם מקללך יש מין מקלל שהוא מברך גם אותו אברך, ולזה אמר לשון יחיד כי לא כל מקלל יברך אלא פרט שהוא מכוין לברכה אבל מברכיך את כולן יברך. ותיבת מקללך נמשכת גם כן למטה כשתהיה קללתו לקללה אאור. נמצאת אומר כי מכוין ה' לגמור כנגד המברכים לברך כולם, והמקללים הם ב' פרטים פרט א' יש שישנה בברכה ונמשכת התיבה למעלה, ופרט א' הם בארירה ונמשכה התיבה למטה:
@3 **עוד** ירצה על זה הדרך, **ואברכה מברכיך**, פירוש כשיהיו לך בברכה אחת ב', שהם המקלל ומתכוין לברכה כמעשה שאמרו תזרע, וחזר האב וברכו, קבע ה' ברכה לשניהם, שלא תאמר כי עיקר המברך הוא הראשון ואין הב' אלא מפרש תלמוד לומר מברכיך כי שניהם יתברכו. ואומרו **ומקללך** יש גם כן להסמיכה למעלה, והוא על דרך אומרם במסכת תענית (כ.) וזה לשונם טובה קללה שקללן אחיה השלוני מברכה שברכם בלעם וכו', וכנגד מקלל כזה אמר שישנו בכלל הברכה ולזה רמז לשון יחיד כי לפרט זה דוקא יכוין לברך, ומקללך פרט אחר שאינו אלא מקלל לזה אאור:
@3 **ונברכו בך וגו'**. וזה הוא ההפרש שבין מברכיך לשאינו מברך ולא מקלל כי מברכו יברכהו ה' בכבודו מפיו אבל שאר משפחות האדמה יתברכו מאמצעות אברהם:
@4 **וילך אברם וגו'**. כל הכתוב מיותר שהרי אומר בסמוך בסדר הודעת ההליכה (פסוק ה') ויקח אברם וגו' ויצאו ללכת וגו':
@4 **אכן** כוונת הכתוב הוא להודיע חיבתו של אברהם שלא נתעכב אפילו שעה אחת אלא בגמר דברי ה' לך לך תכף וילך אברם ולא נתעכב לשום סיבה ועזב את אביו ומולדתו. ושעור תיבת כ''ף כאשר הודעת הזמן שהיה סמוך לדבר ה' אליו. והודיע הכתוב כי לוט לצד דביקותו באברהם הלך אתו פירוש לא לצד קיום מאמר ה' אלא ראהו הולך והלך עמו. וכוונתו בהודעה זו כי הגם שנתחכם אברהם לחפוז ללכת לבל יתחברו עמו ממולדתו ומבית אביו אף על פי כן לא הועיל בערך פרט זה והלך אתו לוט:
@4 **עוד** ירצה להיות שאמר לו ה' הבטחות תועליות הרבה כשילך לו מארצו וכו' אם כן הגם שילך יסבור הרואה כי אין להחזיק לו טובה על זה שאפילו קל שבקלים כשיראה כל התועליות ימהר ליסע לזה הודיע הכתוב צדקותו של אברהם כי מה שהלך לא לצד הבטחות האמורות אלא לעשות דבר ה'. ודקדק לומר **כאשר דבר** ולא כאשר אמר כמו שהתחיל בתחילת הפרשה ויאמר ה' לאמת כדברינו. והוא, יש לך לדעת כי כל מקום שיאמר הכתוב דיבור יגיד על דבר קשה והאמירה היא רכה וכאן הזכיר בתחילת הפרשה ויאמר ה' לצד שכל הדבר הוא להנאת אברהם ובמעשה אכרהם אמר כאשר דבר פירוש שעשה הדבר לצד גזירת מלך עליו ולא לתועלת הנמשך לו:
@4 **עוד** ירצה להודיע כי אברהם הלך כאשר דבר אליו ה' בסמוך, ומה נאמר בדברי ה', אל הארץ אשר אראך, שלא הודיעו מקום אשר יבא שמה ואף על פי כן הלך מארצו וסמך על מה שיודיעהו ה' כשירצה מבלי חשוב לומר איך אצא מהעיר קודם שנדע המקום וזה נסיון גדול, ואחר כך הודיע הכתוב הוצאת את אשר עמו שלא ניסה ה' אותם בדבר זה אלא הודיע המקום ואחר כך יצאו, והוא אומרו בפסוק שאחרי זה **ויקח אברם** וגו' **ויצאו ללכת ארצה כנען**, ולא הוצרך הכתוב להודיע כי ה' הודיעו המקום כי הוא מובן מעצמו:
@6 **ויעבר אברם וגו'**. מודיע הכתוב כי היה אברהם עובר בארץ ממקום למקום ואין אומר אליו דבר מבני הארץ והגם שבעלי הארץ שהם כנען היו אז בארץ אשר עבר אברהם שמה לא פצה פיו וצפצף:
@6 **עוד** ירמוז כי אברהם היה עובר ולא היה מחזיק עצמו בחשיבות אלא עברי, על דרך אומרו (לקמן י''ד י''ג) אברם העברי. וטעם אומרו **והכנעני** וגו' ולא הספיק במה שאמר בפסוק שלפני זה ארצה כנען, כאן הודיע זמן שנכנסה לרשות הכנעני, ומה שקדם ואמר ארצה כנען, אין ראיה, כי קראה כן על שם העתיד:
@6 **או** אפשר שרמז בשם כנען על דרך מה שדרשו ז''ל (ילקוט) בפרשת שלח לך וגו' ארץ כנען שרמז אל ישראל שבאו מאברהם בן מאה שנה ושרה בת תשעים שנה הרמוזים בחשבון תיבת כנען לזה הוצרך להודיע **והכנעני אז בארץ**:
@6 **עוד** ירצה בהודעת **והכנעני** לומר פתח הזכיה בארץ כי הכנעני היה אז בארץ שהוא עבד דכתיב (לעיל ט' כ''ה) עבד עבדים יהיה לאחיו אין לו קנין וכל התופם בקנייניו מבני שם או יפת יזכה בהם ובאדמתם, ובא הקב''ה וזיכה הדבר לאברהם, וזולת זה אם לא היה הכנעני אז בארץ אלא מבני יפת לא היה מקום להוציאם מידם אחר שזכו בה. ורז''ל אמרו (תו''כ פ' קדושים) כי של בני שם היתה ואברהם מבני שם זכה קודם בה, ולדרכם הודיע ה' כי לא זכה להיותו כנעני יד עבד כיד רבו:
@6 **עוד** ירצה, להיות שרצה לומר ה' אל אברם לזרעך אתן את הארץ, ועד עתה יודע הייתי כי הארץ של שם היתה ואברהם מבני בניו הוא ואין ידוע כי של כנען היתה אז, ויאמר האומר מה נותן לו ה' דבר אשר שלו הוא מאז ומקודם, והגם שציינה מקודם לכנען כבר פירשתי שאין ראיה מזה, אשר על כן הודיע ה' **והכנעני אז בארץ** ולזה הוצרך ה' להבטיחו שיתננה לזרעו:
@7 **וירא ה' אל וגו' ויבן שם וגו'**. כונת הכתוב להודיע הפלגת חיבת אברהם בקונו, כי ה' נגלה אליו ובשרו בזרע ובנתינת הארץ והוא לא החשיב בשורת ב' מעלות טובות לכלום בערך שמחתו בגילוי שכינתו יתברך אליו, לקיים מה שנאמר (תהלים טז) שובע שמחות את פניך, והוא אומרו **ויבן מזבח לה' הנראה אליו**, כאן פירש סיבת שמחתו אשר עליה בנה מזבח הוא לצד הראותו יתברך אליו והבן. וזה אות לבניו כמה מהם אשר הרחיקו חשק הזרע בערך חשק התורה והמצות, וצא ולמד מבן עזאי (יבמות סג:) בטענתו ומה אעשה ונפשי חשקה בתורה:
@8 **ויעתק משם וגו'**. לא זכר למי העתיק, ורש''י ז''ל פירש אהלה, והוא חסר. ואולי כי רמז שהעתיק צור ממקום שנראה אליו שם, והוא אומרם ז''ל בברכות (ה:) בפסוק (איוב יח) הלמענך תעזב ארץ ויעתק צור ממקומו, כי בצאת ישראל ממקום תפלתו גורם שיעתק צור שהוא הקב''ה ממקומו, ומכל שכן במה שלפנינו שנראה ה' אליו ובנה לו מזבח שם וכשיעבור משם אברהם יעתק צור ממקומו והוא אברהם המעתיק:
@8 **עוד** ירצה שהעתיק מזבח שבנה שם כשרצה להטות אהלה במקום אחר סתר המזבח שבנה וחזד ובנאו במקום אשר עשה שם אהלה, ולא הוצרך לפרש כי סמך על הזכרתו בסמוך ויבן שם מזבח וגו' ויעתק משם. גם הראה באצבע באומרו משם שחוזר אל האמור בסמוך והבן:
@11 **ויהי כאשר הקריב וגו' הנה נא ידעתי וגו'**. רז''ל אמרו (ב''ב טז.) להגיד צניעות שהיה ביניהם. וצריך לדעת לאיזה ענין אמר לה כן אברהם:
@11 **אכן** להיות כי רצה לצוות עליה לומר אחי הוא חש שתאמר שרה למה הכניסה בגדר סכנה שעל כל פנים היא מסתכנת או תמסר בעל כרחה ביד הטמאים על ידי הריגת הבעל או ברצונה ולא היה לו להביאה למקום כזה, והגם שבטוחים הצדיקים בהקב''ה אף על פי כן כלל זה בידינו שאין סומכין על הנם ומה גם לגבי בחירת האדם, וצא ולמד (קידושין לט:) משמואל שאמר (ש''א טז) ושמע שאול והרגני, לזה אמר אליה **הנה נא** וגו' נתן התנצלות על הדבר כי עתה נודע לו ולא מקודם שאם היה יודע מה שידע עתה לא היה מביאה אל מצרים והיה הולך למקום אחר. וטעם נתינת לב לדעת לצד קרבתו לבא למצרים ראה פנים כעורות. או ידע בקריבת העיר כי המלך יקח היפה בנשים ונתן דעתו והכיר בה. ואומרו כי אשה יפת וגו' ולא הספיק לומר כי יפת מראה את, נתכוין לומר כי אחת היא בעולם אשה יפת מראה היא ואין דומה לה והבן:
@11 **ואל** יקשה בעיניך שהלך עמה לארץ פלשתים אחר שידע כי אשה יפת מראה היא, כי ארץ פלשתים לא היו כעורות כל כך כמצרים. ולזה תמצא שלא הוצרך לצוות עליה שתאמר היא אלא הוא אמר עליה אחותי היא כי לא היה בית מיחוש כאנשי מצרים שהיו בתכלית הכיעור והיא כתכלית היופי:
@12 **והיה כי יראו וגו'**. הקדים לומר לה טעם למה שמצוה אותה בסמוך **אמרי נא** וגו', שתאמר מאז ותודיע מבלי שואלה דבר תשתדל להשמיע כי היא אחותו, והוא אומרו **אמרי נא** פירוש עתה מבלי שואל, ולצד שתאמר למה נצטרך להודיע דבר מבלי שואל, לזה אמר כי זולת זה לא תהיה שאלה וכשיראו אותם ידעו מן הסתם כי היא אשתו, והוא אומרו **והיה כי יראו** וגו' לא ישאלו דבר כי מעצמן יאמרו ודאי אשתו זו ולצד אומרם כן בדעתם יהרגו אברהם, לזה הקדים הוא להוציא קול אחוה לכל מכיר ורואה אותם:
@13 **למען ייטב וגו'**. פירוש טעם שאני מצווך לומר אחותי ולא אני מוסיף להרחיק יותר שתאמר עליו איש נכרי הוא אצלה, **למען ייטב** וגו' ואם יהיה נכרי אין לו ענין שיטיבוהו בשבילה. ואולי כי לזה הקפיד שתאמר היא ולא הספיק שיאמר הוא כי לא יצדיקו דבריו להטיבו. ולפי הפשט לא הספיק לומר הוא כי חשש שתאמר דבר שיוכר ממנו כי אשתו היא. ואומרו **וחיתה** היא תכלית הטובה שמקוה להחיות נפשו ברעב. ודקדק לומר **וחיתה נפשי** ולא אמר ואחיה וכו' לרמוז אומרו (משלי יג) צדיק אוכל לשובע נפשו:
@13 **עוד** ירצה בדקדוק עוד אומרו כפל ענין בעבורך ובגללך שהיה לו לומר ייטב לי וחיתה נפשי כגללך או בעבורך:
@13 **אכן** נתכוון לב' דברים הא' למען יטיבו לו בעבור אחותו טובה גשמיית. ועוד **וחיתה נפשי** וגו' על דרך מה שדרשו ז''ל (ברכות לא:) בפסוק (ש''א א) אם ראה תראה שאם לא יפקידה תעשה שעל כרחך יראה לתת לה זרע ע''י שתלך ותסתר וכו' ותבדק כסוטה ונזרעה זרע. כמו כן חשב אברהם כי על ידי סתירת האשה עם האיש והיא נקיה ה' יפקדנה בבנים בדומין לו והוא אומרו **וחיתה נפשי** בפקודת הזרע בגללך פירוש בדברים המתגלגלים ממך על דרך מה שדרשו ז''ל (שבת קנא:) בפסוק בגלל הדבר וגו', ולזה הפסיק בתיבת בעבורך לומר כי הם ב' דברים. גם אומרו **וחיתה** בתוספת וא''ו לומר שהוא פרט חדש ואינו ענף ייטב לי כי הם ב' בחינות ההטבה אחד לגוף ואחד לנפש. ודבר זה הושג אצלו בסתירה שנסתרה עם אבימלך ולא בפעם הזאת עם פרעה לטעם כי שם לא היה חשד כי גירשו מארצו גילה כי לא עשה דבר. או אפשר כי באמצעות ב' פעמים נתפרסם הקול על שרה כי נסתרה ועל ידי זה נפקדה. שוב בא לידי מאמר רז''ל (ב''ר פנ''ג) וזה לשונם אמר רבי יצחק אמר הקב''ה כתיב (במדבר ה כח) ואם לא נטמאה האשה וטהורה היא ונקתה ונזרעה זרע וזו שנכנסה לבית פרעה ולבית אבימלך ויצתה טהורה אין דין שתפקד עכ''ל, והם דברינו עצמם והבן. הרי שחיתה נפשו של אברהם בבנים בגלל שרה:
@17 **וינגע ה' וגו' על דבר שרי אשת וגו'**. פירוש כי בשעת הנגע הודיע כי שרי היא אשת אברם:
@18 (יח יט) **ויקרא פרעה וגו' למה וגו'. למה וגו'**. קשה למה כפל הקושיא ב' פעמים באופן משונה. ואולי שיכוין לומר ב' הדרגות בתמיהתו על זה הדרך, הא' מן הראוי היה לך לחוש לי שמא לא נדע כי היא אשתך ואקחנה, ועוד שהוספת לעשות במה שאמרת בפירוש אחותי היא:
@18 **עוד** יתבאר על דרך אומרם ז''ל (רש''י) כי טעם פרעה שאמר לו הנה אשתך קח ולך ואבימלך אמר אליו הנה ארצי לפניך וגו' כי פרעה להיות אנשיו כעורים ושטופי זמה חש על הדבר שיכשלו בו ויענשו מה שאין כן אבימלך שלא היו כעורים וכו', ולזה תמצא שאבימלך אמר אליו מה ראית כי עשית וגו' מה שאין כן פרעה כי יודע טעמו של אברהם כי ירא פן ימות עליה, ומעתה יתבאר הכתוב על נכון להיות שידע פרעה הטעם לא יוצדק לומר לו למה אמרת אחותי היא כי אם שאלה ראשונה למה לא הגדת לי בייחוד כי היא אשתך, ובזה, הגם שתאמר אחותי היא תהיה לך שמירה מהעם ולא היית גורם לי רעה להכשל בה, כי פרעה היה מחזיק עצמו ודאי שלא יעשה דבר מגונה ביודעו כי היא אשתו ולא יחשדנו אברהם. וההגדה היתה מועלת לאברהם לאחד מב' דרכים או יצו עליו פרעה אנשים לשומרו כאשר עשה אחר כך בזמן מועט, או היה ממהר לשולחו. והוסיף לומר **למה אמרת** וגו' פירוש ואם תאמר וכי חובת גברא הוא שכל איש אשר יביא את אשתו ילך ויגיד לפרעה כי אשתו זאת, לזה אמר למה אמרת וגו', ומהטעם עצמו שאמרת אחותי היא לצד מעלת יופיה לזה עליך בפרט מוטל להודיע:
@18 **או** יאמר על זה הדרך **למה אמרת** וגו' וכיון שאמרת היה לך לחוש לי לקחתה לאשה, הן אמת אם לא היית אומר אני הייתי חושש לה מאשת איש אבל כיון שאמרת אחותי היה לך לחוש לי שאקחנה לאשה ותגיד לי בסוד. ולא השיב אברהם דבר כמו שהשיב לאבימלך כי אברהם טעמו היה שהיה חושד לפרעה עצמו ואין ראוי להשיב על זה. ואולי כי לזה חש פרעה ומיהר לשלחו מארצו וזולת זה יצו עליו בתמידות אנשים:
@28 **אל נא תהי מריבה וגו'**. טעם אומרו **ביני ובינך**, הודיעו כי סופה להיות המריבה גם בין שניהם. והגם שיאמר לוט כי ח''ו לא יריב את רבו וגאונו ולא יהיה הדבר אף על פי כן יודה בדבר אשר כבר הוא בין רועיו ורועי אברם, והוא אומרו **ובין רועי** וגו'. ואומרו **כי אנשים אחים** יתבאר על פי דבריהם (ב''ר פמ''א) כי רועי לוט היו משלחים צאנם ורועים בשדות אחרים בטענת כי הארץ לאברהם ולוט בן אחיו יורשו, וזה הוא שיעור הכתוב אל נא תהי מריבה ביני וגו' במאמר זה שאנשים אחים:
@28 **עוד** יתבאר על דרך אומרו (תהלים נ) תשב באחיך תדבר בבן אמך תתן דופי ופירשו קדמונינו על זה הדרך תשב באחיך בבן אמך שהוא אתה המדבר תתן דופי, והוא אומרו כי אנשים אחים פירוש וכשתהיה המריבה ויוגשו לפני שופטי ארץ שהם הכנעני והפריזי שאמר הכתוב בסמוך, אשר ירשיעו שופטי ארץ מהשנים יסובב הפגם גם לאחיו, כי הנושך והנשוך ענושים להיותם אחים:
@28 **עוד** ירצה כי להיותם אחים אין לוט ולא רועיו מתנהגים בכבוד הצריך לאברהם בחושבם כי אין הפרש מה שאין כן אם היו אברהם ולוט בלתי קרובים היו נוהגים כבוד באברהם לצד רוממות כבודו אשר גדלו אלהים:
@34 **וה' אמר וגו'**. טעם שלא התחיל לומר ויאמר ה' אל אברם אחרי וגו', יכוין לומר להיות שאמר הכתוב ויאמר אברם אל לוט וגו' הפרד נא וגו' והפריד רשע מעליו מוסיף הכתוב לומר שגם ה' היה יושב ומצפה אל הדבר ותיכף ומיד שנפרד הרשע דבר אליו והראהו את הארץ. והוא מה שאמר לו (י''ב א') אשר אראך וכמו שפירשנוהו במקומו:
@34 **וראה מן המקום**. טעם שהוצרך לומר **מן המקום אשר אתה שם**. כאן עשה לו נם עצום שיוכל לראות מצפון לדרום וממערב למזרח ממקום אחד מבלי שיוצרך לס ובב:
@35 **כי את כל הארץ וגו'**. הנה ידוע כי שיעור חוש הראות הוא מוגבל באדם את אשר ישיג לאור השמש, וכאן עשה לו ה' נם שנתקרבו קצות הארץ וראה הכל ובאמצעות הדבר החזיק בכל הארץ כי אין לך חזקה גדולה מזו שיעתק צור ממקומו להתקרב לפני אדוני הארץ, ולא ירחיק דעתך דבר זה כי מצינו שקפצה הארץ לעבדו (ב''ר פנ''ט) וגם נקפלה תחת בניו (חולין צא):
@37 **קום התהלך בארץ וגו'**. בפרק המוכר את הפירות (ב''ב ק.) וז''ל תניא הלך בה לארכה ולרחבה קנה בה מקום הלוכו דברי רבי אליעזר וחכמים אומרים לא קנה עד שיחזיק מאי טעמא דרבי אליעזר דכתיב קום התהלך וגו' לארכה וגו', ורבנן התם משום חביבותא דאברהם וכו' כדי שיהיה נוח ליכבש לפני בניו ע''כ. הנה לסברת ר''א הגם שהחזיק בתלישת הארץ וסמיכתה לפניו כמו שפירשנו בפסוק כי את כל הארץ וגו' אף על פי כן ממה שאמר הכתוב **קום התהלך** וגו' ללמד תורה בא שהליכה הוה חזקה. ולסברת חכמים דמשום חביבותא וכו' חזקת הארץ לזכות אברהם זכה מדין הכתוב למעלה ואין למידין מכתוב זה כי חביבותא דאברהם יכוין:
@39 **ויהי בימי** וגו'. טעם סדר הודעת הענין, לומר כי ד' מלכים אלו תקיפים היו צא ולמד עזר אלהים שעם אברהם אשר מחה הד' מלכים בחצי הלילה ושאר התועליות:
@50 **ויקחו וגו' בן אחי אברם וגו'**. טעם שהוצרך לומר בן אחי אברם, גם טעם אומרו **והוא יושב בסדום** ללא צורך שכבר ידענו כי שם קנה מקומו, יכוין לומר שהמלכים ידעו כי לוט זה הוא בן אחי אברם ואף על פי כן לקחו אותו והוליכוהו בשביה, ונתן הכתוב הטעם שלא חששו לכבוד אברהם והוא היה נכבד ומעולה בעיני כל העולם כי להיותו יושב בסדום, והוא על דרך אומרם ז''ל מואב טהר בסיחון ע''כ, הרי שהגם שפטר ה' מואב מיד ישראל כיון שנמצאו בסיחון הותר להם. כמו כן לוט הגם היותו בן אחיו של איש שלומם אף על פי כן כיון שנמצא בסדום הותר להם. ובזה מצאנו נחת רוח לטעם אברהם אשר לא קרא לשלום לד' מלכים להשיב לוט ואם לא ישלימו אז יכם כאשר הכם, אלא הטעם הוא להיות שידוע היה להם לוט היותו בן אחי אברהם, ולזה רמז הכתוב באומרו **וישמע** וגו' **כי נשבה אחיו** פירוש שנשבה אחר שידוע שהיה אחיו של אברהם ובזה גילו כי אויבי אברהם הם ולזה רדף אחריהם ויכם:
@50 **ואם** תאמר הלא הדין הוא עם ד' מלכים שלקחוהו מתוך העיר המורדת בהם. ויש לומר שמה שאנו אומרים טהרו בסיחון הוא לאומה שאין לנו עמה לא שלום ולא מלחמה אבל אנשי שלום לא נדין לשבותם, וצא ולמד מה שעשו ישראל לקני שציוו עליו (ש''א ט''ו) סרו רדו מהעמלקי וגו' וכמו כן היה להם לצוות עליו לעבור מביניהם אם הם אנשי שלום עם אברהם:
@54 **וגם את לוט וגו'**. הגם שעיקר רדיפתו היתה עליו ואותו היה לו להקדים. הודיע הכתוב סדר ההצלחות בדרך לא זו אף זו, א' השיב הרכוש של המלכים, הצלחה ב' שהשיב לוט ולא שרפוהו המלכים בראותם במלחמה עם אברהם לנקמה. והודיע הכתוב שנתן דעתו להשיב הנשים והטף לצד כבוד שעשו ללוט:
@56 **ומלכי צדק וגו'**. רבותינו אמרו (נדרים לב:) כי הוא שם. וטעם שהפסיק בענין מלך שלם בין יציאת מלך סדום להודעת דבריו אל אברהם וכו', להגיד שבח הצדיקים מה בינם לבין הרשעים כי מלך סדום יצא לקראת אברהם לראות פניו ריקם הגם שאליו יחויב להקביל פני אברהם במנחה כיד המלך והוא הרשע יצא בידים ריקניות, ושם הצדיק מבלי חיוב נדיבות יעץ והקביל פניו בלחם ויין:
@56 **עוד** ירצה על דרך אומרם ז''ל (יומא כח:) קיים אברהם אבינו אפילו עירובי תבשילין שהם תיקוני רבנן, ולזה הודיענו הכתוב, כי אברהם שר וגדול ומכובד בעיני הכל היה, וכשיצא לקראתו מלך סדום מן הסתם יקביל פניו בתשורת לחם לו ולעבדיו ואנשי מלחמתו, ולצד כי אברהם יפרוש ממאכלם, מהלחם משום פת של גוים, והיין משום סתם יינם, לזה נתחכם ונשתדל מלך סדום שיעשה תשורת האכילה על יד נאמן שהוא שם ומידו של שם לידו של אברהם. וחידוש השמיענו הכתוב שאפילו לחם ויין שאינן אלא מדרבנן הקפיד אברהם ומכל שכן שאר דברים שיש בהם חשש איסור תורה:
@56 **עוד** ירצה הכתוב להודיע טעם אשר ממנו עלה על דעת מלך סדום לומר לאברהם והרכוש קח לך ולא שאל הכל, לזה אמר **ויצא מלך סדום לקראתו** ואחר צאתו יצא מלך שלם וכו' ונתן לו אברהם מעשר מכל, מזה הרגיש מלך סדום, כי הרי זה מגיד כי קנייניו הם שאין אדם מעשר ממה שאינו שלו, לזה שאל ממנו הנפש והרכוש אסכים לדעתך שתקחם לך, והוא אומרו **קח לך** והרי זה מגיד כי עוד היה לו טענה להחזיק בכל, וכדי שלא יכנם עמו במחלוקת פשר ואמר (פסוק כא) תן לי הנפש והרכוש לא ארד עמך לדין אלא הריני מסכים שתקחנו, ועיין טעם הדבר בפירוש פסוק תן לי הנפש:
@56 **והוא כהן וגו'**. פירוש הוא כהן אבל זרעו אינו כהן שנתנה כהונה לאברהם דכתיב (תהלים קי.) אתה כהן לעולם, ואומרו על דברתי מלכי צדק כי הוא ברך את אברהם שיהיה כהן לאל עליון וברצונו נתן הדבר לאברהם כאשר אבאר. ואומרו **לאל עליון**, להיות שהיה להם אלוהות אמצעיים כידוע לכסילים אמר כי זה כהן לאל עליון על כל האלוהות שהיו להם אז. ורז''ל אמרו (נדרים לב:) כי בעון שהקדים ברכת אברהם לברכת קונו נטלה ממנו כהונה, ולדבריהם ז''ל אומרו **והוא כהן** תתפרש גם כן למעט משם והלאה שמעטו הכתוב על חטאתו האמור בענין, והגם שהקדים המיעוט לחטא מה בכך כי התורה נכתבה אחר כך:
@57 **ויברכהו ויאמר**. צריך לדעת אם הברכה שברכו היא המוזכרת בענין ברוך אברם אם כן לא היה צריך לומר ויברכהו ורואני מאומרו ברוך אברם שברכו:
@57 **עוד** היה לו לומר ויברכהו לאמר ברוך וגו' על דרך אומרו (ויחי מח) ויברכם ביום ההוא לאמר וגו':
@57 **אכן** הכוונה היא מתחלה ברך אברהם פירוש ברכה הנוגעת לו שלא יפול ביד אויביו ויישר חיליה שהם ברכות הגופניות, ואחר כך אמר ענין אחר לצד עילאה ימלל ברוך אברם וברכתו תהיה לאל עליון שהוא יעבוד האל ושבאמצעותו יהיה האל קונה שמים וארץ, וכך היה שבאמצעות אברהם נתן השם חיי עולם לבניו ונתקיימו שמים וארץ, וכאומרם ז''ל (ע''ז ג.) שתנאי התנה ה' עם מעשה בראשית וכו', וכאומרם (שבת פח) בפסוק (תהלים עו) ארץ יראה וגו' הרי כי לולי אברהם אין לה' קנין שמים וארץ והבן:
@57 **עוד** ירצה על זה הדרך **ויברכהו** וגו', להגיד בא כי ב' ברכות האמורות בדבריו הם ברכות הנוגעים לאברהם ואפי' ברכה שאמר ברוך אל עליון אשר מגן היא ברכת אברהם כשמתברך ה' באמצעותו אשר מגן וגו', ולעולם לא ברך אלא ברכות האמורים בענין:
@58 **וברוך אל עליון**. רז''ל אמרו (נדרים לב:) שנענש על אשר איחר ברכת ה' והקדים ברכת אברהם וניטלה ממנו הכהונה.
@58 ואפשר שטעם שם הוא שלקח סדר המעשה כי אברהם הוא מעצמו הכיר בוראו והשתדל באמונתו יתברך ואליו יאות הברכה ואחר כך ברך לה' שנתרצה בו, וכן ראוי לעשות, וללמד הוא בא שאין הקב''ה מתרצה אלא במי שמתרצה בו קודם, והוא אומרו ברוך אברם לאל עליון שהוא הכשיר עצמו להיות עבד לאל עליון ולזה ברוך הוא אל עליון אשר מגן וגו', ודרך זה לא יוצדק אלא במבורך קודם. וכפי זה לא נענש שם אלא הוא מעצמו נתנה לאברהם וכמו שפירשתי בפסוק והוא כהן. או אפשר שנענש על הנשמע משטחיות המאמר שנראה שלא חש להקדים עבד לרבו הגם שנתכוין לטובה, ומצינו שיעניש ה' על כיוצא בזה בכמה מקומות:
@59 **תן לי הנפש והרכוש וגו'**. צריך לדעת לאיזה ענין הוא אומר לו **והרכוש קח לך** הלא לקוח הוא אצלו ולא היה לו לומר אלא דבר שהוא שואל ממנו שיתן לו בתורת מתנה, כי מאומרו קח לך מגיד כי צריך הוא להסכים שיקחנו וזה מנגד לאומרו תן לי הנפש:
@59 **אכן** יתבאר הענין על דרך מה שאמרו ז''ל בפרק הגוזל ומאכיל דף קי''ו וזה לשונם תנו רבנן שיירא שהיתה מהלכת ועמד עליה גיים וטרפה ועמד אחד והציל הציל לאמצע ואם אמר אני מציל לעצמי הציל לעצמו, ומפרש רב אשי כשיכולין להציל בני השיירא על ידי הדחק, לזה אם הציל סתם לאמצע, פירוש כל אחד יכיר את שלו ויטלנו, וכמו שפירש''י. ואם אמר לעצמי אני מציל ושמעו בני השיירא ושתקו גילו דעתם דאייאוש ולא מסרו עצמן ולעצמו הציל ע''כ. וסבר מלך סדום שהוא לא נתיאש ועודנו עומד להציל וישכיר גייסות עליו, וכשהלך אברהם להציל הגם שיאמר שגילה דעתו שלעצמו מציל אינו מועיל וצריך שישמע מלך סדום דבריו ויסכים וזולת זה לאמצע הציל ולא יטול אלא מה שהוא שלו שהוא לוט ורכושו. ותמצא שמלך סדום היה מחזיק עצמו במדרגה גדולה שכן אמרו במדרש וז''ל (ב''ר פמ''ג) ויצא מלך סדום וגו' התחיל מכשכש בזנבו אתה ירדת לכבשן האש וניצלת ואני ירדתי לחמר וניצלתי ע''כ. הרי שהחזיק עצמו בבעל היכולת:
@59 **ובזה** יתבאר הכתוב **תן לי הנפש** וגו', פירוש אני כפי סברתי לאמצע הצלת כי לא נתיאשתי ולא הודעתני שאתה מציל לעצמך ושתקתי אלא לפי סברתך שאתה נותן מעשר נראה שאתה סובר שאין מציאות לי להציל אפילו על ידי הדחק, ובזה אינך צריך לגלות דעתך, לזה, כדי שלא נכנס במחלוקת נסכימה יחד לפשר, אתה תבטל זכותך ותחליט לי הנפש, ואני אבטל זכותי ואחליט לך הרכוש קחנו לך, והבן. והוא הפחות טועה היה כי מושלל הוא מהצלה, ולא חלק רב אשי אלא בגייס שטרף והלך לו אבל במציאות שלפגינו כבר העריכו מלחמה ואבדו ואין לך אינן יכולין להציל בזה שכבר בטלו במיעוטן ונתייאשו ודאי ובטענת שקר הוא בא בכשכוש זנבו. ותמצא שלא הצריך רב אשי שיאמר בפי' לעצמי אני מציל אלא דוקא ביכול להציל על ידי הדחק אבל אם אינו יכול להציל אינו צריך לומר לעצמי וכו', וכן הוא מבואר שם. ואם כן הגם שיאמר אחר כך יכול הייתי להציל אין טענתו טענה וכן פסקו רמב''ם (הל' גזילה ואבידה פי''ב) והרא''ש:
@59 **ותמצא** שרמזו ענין [זה] רז''ל במתק לשונם באומרם מכשכש בזנבו, פירוש שאחר שרואה עצמו שניטל ראשו עדיין הוא מכשכש בזנבו, כי בהיותו בכל תוקף מלכותו וד' מלכים אשר אתו לא עמדו בפני הד' מלכים, ומכל שכן אחר הורדת עדיו היכול יוכל להציל, הא למדת שאברהם הציל לעצמו וקנה הכל ולזה נתן מעשר מכל שהגם שיוותר למלך סדום אדם רשאי בשלו לא במעשר שהוא של גבוה:
@60 **ויאמר אברם אל מלך וגו'**. טעם הרמת ידו היא כדי שיתאמת אצל מלך סדום שאין דעתו עוד לחזור בו בדבר הזה לא כולו ולא מקצתו, ואומרו **אם מחוט** וגו' ואם אקח, שלא היל''ל אלא אם אקח מחוט וגו', נתכוון לומר על זה הדרך **הרימותי** וגו' **אם מחוט** וגו' פי' הרי הוא עלי כתרומה אם לקחתי מחוט ועד וגו' מהרכוש האמור בענין, ועוד הוסיף שלא יקח לעתיד מכל וכו' והוא אומרו ואם אקח וגו':
@60 **עוד** יכוין לומר על זה הדרך **הרימותי ידי** פירוש נתתי תרומה שאני חייב מהכל אם מחוט ועד וגו' מה שאני חייב כפי הדין, ושלא תאמר שאני להוט אחר הממון ותובע מה שאינו שלי ואם אקח מכל וגו', אבל לא מפני הותרנות אהיה גוזל לגבוה מה שאני חייב לתת לו שהוא תרומת מעשר:
@61 **ולא תאמר אני וגו'**. וקשה איך יוצדק לומר שהוא העשיר וכו' והלא האדון ה' צבאות הוא מגן צריו:
@61 **אכן** לפי מה שפירשנו בדברי מלך סדום כי חושב שהנכסים אליו נוגעים אלא שמתרצה לתת לו הרכוש כאומרו והרכוש קח לך, לזה אמר שזה עושה לצד דעתו, שהוא חושב שהנכסים שלו, שלא ימלא פיו לומר אני העשרתי את אברם הרימותי וגו' אם וגו'. ובזה, לא תאמר אתה וגו' ולעולם כפי הדין נכסי הם אשר נתן לי אלהים ולזה נתתי מעשר מכל, וכמו שהוכחנו בפי' (פסוק כא) תן לי הנפש וגו'. ובזה ידויק אומרו **ולא תאמר** שהיה לו לומר ולא אתעשר משלך והבן:
@62 **הם יקחו חלקם וגו'**. פירוש לא שיהיה הרשות בידך ותכנם עמהם בשיעורין אלא הרשות בידם לקחת אשר ישפוטו הם כי הוא הנוגע להם. גם בזה הראה לו כפי האמת אליו נוגעים הנכסים, אלא שחש לאמירה, הגם שהיא כוזבת אף על פי כן ממעיט בכבודו של אברם באמירתו:
@65 **ויאמר אברם הן לי וגו'**. קשה א' איך יוכל לומר **לא נתת** וגו' והלא כבר הבטיחו ואמר לו (לעיל יג טז) ושמתי זרעך כעפר הארץ ומה לו לפקפק ח''ו בדברי ה'. ב' אומרו הן לי היה לו לומר הן לא נתת לי. ג' צריך לדעת הכוונה באומרו **והנה בן ביתי יורש** אחר שאין לו זרע מה לי אם יורש אותו בן ביתו או אחר:
@65 **אכן** כונת הכתוב היא על זה הדרך, שלהיות שבשורת הזרע שאמר לו ה' אמר כעפר הארץ, ודבר ידוע כי הנמשלים לעפר הארץ הם בני אדם הבזוים והפחותים שאין בהם נפש קדושה, על דרך אומרו (קהלת ג) רוח הבהמה היורדת היא למטה לארץ, והם הנקראים עמי הארץ, ובני אדם כאלו לא יתמלא רצון הצדיקים בהם, לזה אמר אברהם **הן לי** וגו', פירוש דבר השוה לי לא נתת זרע. ולזה השיבו ה' ואמר לו ספור הכוכבים כה יהיה זרעך והם הצדיקים המשולים לכוכבים דכתיב (דניאל יב) ומצדיקי הרבים ככוכבים ובזה נחה דעתו. ואל יקשה לך לפירוש זה ממאמר רז''ל שדרשו בפסוק והיה זרעך בעפר הארץ שאמר ה' ליעקב, וז''ל (כ''ר פס''ט) כעפר וגו' מה עפר אינו מתברך אלא במים כך בניך וכו' מה עפר מכלה כלי מתכות כו', ע''כ, הרי דהמשלת העפר לשבח. הנה לא דרשו ז''ל בדרך זה לשבח שבעפר, אלא אחר שמצינו שהמשילם ה' לכוכבים הא למדת שלא המשילם לעפר אחרי כן אלא לשבח שבעפר, לא לבחינת הפחיתות, ולזה תמצא שלא דרשו כן בפסוק ראשון הנאמר לאברהם אלא בפסוק הנאמר ליעקב אחר שהובטח אברהם ככוכבים, ולזה דאג אברהם על המשל ראשון כעפר הארץ. ובזה נתיישבו ב' הדקדוקים למה לא הובטח אברהם בהבטחה ראשונה גם דקדוק אומרו **הן לי**:
@65 **ואומרו והנה בן ביתי יורש אותי**, תתפרש בשני דרכים, הא' שאם לא יתן לו אלא כעפר יותר יבחר לבן ביתו לירש אותו, להיותו תלמידו החביב לו, ממה שירשנו בן שאינו הגון, ומצינו שעשו כיוצא בזה אנשי מעשה מבני ישראל המה:
@65 **והב'** על זה הדרך כי מלבד שהיה מצטער על הזרע גם היה מצטער על דברת הבן בית שהיה אומר כי הוא היורש, וזה הוא שיעור הכתוב, והנה, פירוש לפי שעה הוא אומר יורש אותי, ואיך יטב ביום טובה לבבו בשמעו את הדברים מבן ביתו. ומצאתי לרז''ל (שם פמ''ד) שאמרו מעין זה שפירשו שבקש אברהם ללכת ערירי ולא יהיו לו בנים שאינם מהוגנים:
@68 **והאמין בה' ויחשבה לו צדקה**. פירוש על דרך אומרם ז''ל (ר''ה ו.) כי דין הצדקה כנדרים שהנודר לגבוה כמוסר להדיוט. והוא שאמר והאמין בה' פירוש הפקיד אצלו הברכה, ואם תאמר והלא עדיין לא הגיעה לידו להפקידה ביד נאמן, לזה אמר **ויחשבה לו צדקה**, פירוש החשיב אברהם מה שאמר ה' אליו שהוא צדקה, וכיון שכן דין מסירה יש לה והאמינה ביד ה':
@68 **עוד** ירצה, להיות שהבטיחו והוא שיהיו בניו צדיקים ודבר זה אינו בידו של הקב''ה כאומרם ז''ל (כרכות לג:) הכל בידי שמים חוץ מיראת שמים אמר הכתוב שהאמין בה' שכן יעשה ולא הרהר אחר מדותיו לומר והלא וכו' ויחשבה ה' לאברהם צדקה שהפליא להצדיק. או ירמוז על זה הדרך שהגם שמאת ה' היתה זאת להיות ל' צדיקים בעולם (ב''ר פל''ה ומ''ט) אם כן הוא חפץ להטות אדם לדרך ישר ואין לאיש הזה משפט צדקה שאמר הכתוב (דבדים ו, כה) וצדקה תהיה לנו כי נשמור וגו' מעתה הל' צדיקים מוכרחים הם במעשיהם, לזה אמר שאף על פי כן ויחשבה ה' לו צדקה פי' לזרע המוזכר בסמוך דכתיב יהיה זרעך כי שם רמז הל' במספר יהיה:
@75 **ויאמר לאברם וגו'**. צריך לדעת למה כפל לומר **ידוע תדע**. עוד צריך לדעת למה אמר **גר יהיה זרעך** ולא אמר זרעך יהיה גר או יהיה זרעך גר כי אין דרך להזכיר המאורע קודם שיזכיר למי יארע. עוד למה לא פירש כוונתו באומרו גר וגו' ועבדום וענו וגו' אם ג' יחד יהיו בכל הד' מאות שנה או חלק מהארבע מאות בגירות וחלק בעבדות וחלק בעינוי. האמת, כי ממה שראינו שכן היה נודעת הכונה, אלא למה לא פירש ה' דבריו:
@75 **אכן** כוונת הכתוב הוא על זה הדרך טעם שכפל לומר **ידוע תדע** לג' סיבות. הא' על דרך אומרם ז''ל (נדרים לב.) וז''ל ירדו אבותינו למצרים בשביל דבר קל שאמר במה אדע, והוא אומרו ידוע, לצד שאתה חפץ לדעת, תדע כי גר וגו'. ב', להיות שאמר ה' בענין ב' דברים, א' פורעניות ואחת הטבה, כאומרו ואחרי כן וגו' לזה אמר ידיעה ב' פעמים. ג' על דרך אומרם ז''ל (ברכות יח:) בפסוק (דברים לד) זאת הארץ אשר נשבעתי וגו' לאמר וגו' שאמר לו ה' לך אמור לאברהם וגו' שבועה שנשבעתי וכו' ע''כ. והוא אומרו ב' ידיעות א' היא מה שמודיעו באותו מצב ואחד שעתיד להודיעו על ידי משה ולזה אמר תדע לעתיד:
@75 **וטעם** שאמר **גר יהיה** וגו', שהקדים המאורע, נתכוון לומר כי הגרות היא כסדר שהיה בה אברהם, ואם היה אומר כי יהיה גר משמע שתתחדש הגרות, ויהיה נשמע שיהיה זמן שלא יהיו גרים קודם ותתחדש להם הגרות, ולא כן הוא שיעור אומרו כי גר יהיה זרעך פי' בגרות יהיה עומד זרעך, ולזה מצינו שחשב ה' שני יצחק ויעקב הגם שהיו בהויתן לגרות אבות, ואם תאמר היה לו לומר כי זרעך גר יהיה וגו', דע כי נתחכם ה' לומר כן לגלות דעתו כי לא לכל זרעו גזר ה' עול השיעבוד והעיגוי ולזה אמר כי גר יהיה זרעיך פי' יהיה לך חלק בזרעך שאינו אלא בגרות ולא ישתו יין מרורות כל עיקר, ואם היה מקדים לומר זרעך גר יהיה וגו' תהיה הכונה על זה **הדרך** זרעך גר יהיה וגו' ועבדום וגו' ואין חלק מזרע מושלל מהאמור בענין שהם גרות עבדות עינוי והוא לא כן חושב כי יש שישנו בגרות לבד, ולזה הפסיק בין הגרות לשאר, פירוש, לומר כי יש מהזרע שהוא מוחלט שאין לו אלא גרות לבד. וזה הוא שיעור הכתוב גר יהיה זרעך בארץ לא להם. זרעך בארץ לא להם ועבדום וגו'. וטעם שלא שיער כמה מהעבדות וכו'. דבר זה אין לו שיעור יכולין להפטר ביום א' על דרך אומרם ז''ל (דב''ר פ''ב) יענך וגו'. ומעתה שלשה הדרגות בענין חלק מהזרע מוחלט מהשעבוד והענוי והם האבות והשבטים והשאר חלק בגלות וחלק בענוי ואין שיעור לזמן העינוי כי אם יזכו יום א' ולא רד''ו שנה, וצא ולמד משבט לוי (ש''ר ה טז) שנדמה לאבות, ודע שגם הם טעמו דבר מה צא ולמד ממשה (שמות ב ג) ותקח לו תיבת גומא וגו' על שפת היאור:
@76 **וגם את הגוי וגו'**. קשה איך יוצדק לומר וגם על מה שקדם שהוא השיעבוד והענוי וזה הטבה לנקום נקם מאויבנו. ב' תיבת **את** מיותרת. ג' אומרו **דן אנכי** דבר ידוע הוא כי הוא הוא השופט. ד' למה הפסיק בין המאורע אשר גזר ה' על בניו במשפט המשעבדים והיה לו להשלים לומר ואחרי כן יצאו וגו' שהוא גמר ענין ישראל ואחר כך יאמר את הגוי אשר יעבודו וגו'. ולזה אפשר שנתכוון לומר בשינוי זה שאחר שישפוט ה' את הגוי יצאו ברכוש ולקח סדר העשוי, וכמו שמצינו שכן היה בתחלה דן אותם ואחר כך השאילום רכוש גדול:
@76 **אכן** משמעות הכתובים יתבארו על דרך אומרם ז''ל (תנחומא בשלח) וחמושים עלו וגו' א' מחמשים ויש אומרים אחד מחמש מאות והשאר מתו במצרים בימי חושך ואפילה כדי שלא ירגישו בהם המצרים. עוד אמרו ז''ל (שמו''ר פי''ד) בפסוק ולכל בני ישראל היה אור וגו' שהיו ישראל מחפשים חדרי חפצי מצרים והיו יודעים וכו' ובאמצעות זה השאילום וינצלו וגו' ועיין מה שפירשתי בפי' פסוק זה במקומו, והוא שאמר ה' לאברהם **וגם את** וגו' פי' מלבד גזירת השעבוד והעינוי וגם תוספת גזירת פורעניות ידון את ישראל כשידון את המצרים להשמיד ולהרוג חלק גדול מהם למר חמשים חלקים ולמר חמש מאות חלקים, ובזה ידויק תיבת **וגם** ותיבת **את**, ואומרו **אנכי** פי' מכה זו לא ידעו בה המצרים כי אם הוא לבדו כי היו בימי החשך. וסמך לזה אומרו **ואחרי כן** וגו' פי' באמצעות אותו המשפט כשיביא המכה ההוא לדון את שניהם גוי עובד וגוי נעבד שהוא מכת החושך אחרי כן יצאו ברכוש וגו' כאמור למעלה כי באמצעות זה השאילום:
@76 **עוד** יתבאר הכתוב במה שנדקדק עוד למה הביא ה' על המצריים עשר מכות ועל הים לקו וכו' אחר שמצינו כי כן גזר הגוזר:
@76 **והנה** הרמב''ם ז''ל בספר המדע (הלכות תשובה פ''ו ה''ה) כתב כי טעם חיוב האומות המשעבדים הוא לצד שלא אמר ה' אומה פלונית וכו'. והשיגוהו רמב''ן וראב''ד כי מה בכך סוף סוף מצוה עושים בקיום דבר מלך. ופירש רמב''ן כי העונש הוא לצד שהוסיפו לענות יותר מידי העבודה אשר גזר ה', ולדבריו אין האומות נענשים אלא על תוספת עינוי. ולדרכו ז''ל יתבאר הכתוב על זה הדרך **וגם את הגוי דן אנכי** פירוש ידין ה' עמו וממוצא דבר אתה יודע כי ירבה יותר משיעור הגזירה, ודקדק לומר **את** פי' ידון אתו עמו הוא בכבודו ובעצמו והוא אומר **אנכי** כי הוא היודע שיעור הגזירה, ושיעור התוספת שעליו יעניש אותם, וכל זה לדרכו של רמב''ן:
@76 **והנכון** בעיני הוא כי כל האומות חייבין ליענש על כל העינוי והצער אשר יריעו לנו והחקירה מעיקרא אינה צודקת, כי האומות טעם אשר יענונו הוא לצד הבדלתנו מהם וקיום המצות אשר אנו מקיימים, וצא ולמד אם היו ישראל עובדים לטלה והיו לעם אחד במצרים לא היו המצריים משתעבדים בהם והיו כאחיהם המצרים, וכן בכל אומה ואומה אשר תשעבד ישראל ותריע הטעם הוא לצד היותינו נחלת שדי. ומעתה מה מקום לטענת שהם שלוחי אל הגוזר והלא אל גזר על אשר עברו ענף אחד מדבריו והם מריעים על שאינם עוברים על כל התורה והיו ככל הגוים בית ישראל, והוא אומרו (זכרי' א) אני קצפתי מעט פירוש על אשר עברו על חלק מהתורה קצפתי מעט והם האומות המיסרים את ישראל אדרבא עוזרים באמצעות העינוי לרעה לעבור על הכל, וכן הוא שהעובר על הדת פוטרים אותו מכל רע ומטיבין לו. והוא אומרו **וגם את הגוי** אני אתדיין עמו כי אני יודע מחשבות אדם ותחבולותיו וטעם העינוי שאינו לצד קיום מצות ה' שגזר עליהם כן, וממוצא דבר אתה יודע כי הגדיל אויב עשות רשע כיון שמיסר לצד שנאתו אין שנאה כשנאת הדת ופשוט הוא כי יתאכזר עליהם בהפלגה. וכפי זה יוצדק לומר **וגם את** וגו' שהוא הודעת ריבוי הצער אשר יעבור על בניו, וסמוך לזה כתב **ואחרי כן יצאו** וגו' פירוש כיון שאין דעתם לקיים מצות ה' ישנם בהשבת הגזילה בכל מה ששעבדו אותם. וצא ולמד ממעשה גביהא (סנהדרין צא.) שתבע מהמצרים שכר כמה שנים ששעבדו בישראל:
@76 **עוד** ירמוז הכתוב על דרך אומרם ז''ל (מגילה כט) גלו למצרים שכינה עמהם וכו' וכתיב (תהלים צא) עמו אנכי בצרה. ועוד אמרו בפסוק (שמות כד) ותחת רגליו כמעשה לבנת הספיר שירמוז אל שעבוד שנשתעבדו ישראל בלבנים וכו', והוא אומרו **וגם את הגוי אשר יעבודו** בהם שם אתם עמם דן אנכי שירמוז אל השכינה שתהיה עמם בגלות, ובזה ידוייק תיבת וגם שהוא תוספת צער, ותיבת **את** ותיבת **אנכי**:
@77 **ואתה תבא וגו'**. קשה למה הפסיק בהבטחת אברהם תוך הבטחות הבנים, והגם שמבטיחו שלא יראה בחייו מהשעבוד של זרעו, עם כל זה לא היתה נפסדת הכונה אם היה מאחר, שגם עתה אין המאמר סמוך לשעבוד אלא לגאולה. עוד צריך לדעת למה כפל לומר בשלום בשיבה טובה ולא הספיק באומרו בשיבה טובה ובה כלול גם כן בשורת תשובת ישמעאל שאמרו ז''ל, ולא יראה שעבוד הבנים:
@77 **אכן** כוונת הכתוב לפי מה שקדם לנו כי הצדיקים ובפרט האבות יקפידו על ניכוי שכר לעולם הנצחי, וצא ולמד (ב''ר פמ''ר) שמצינו לו שהיה מיצר בהריגת המלכים שמא נתנבה לו משכר העליון עד שאמר לו ה' (פסוק א) אל תירא אברם וגו' שכרך הרבה, אשר על כן כשהבטיחו שיצאו מהשיעבוד ברכוש גדול, יש מקום לאברהם לחוש ולומר כ צר ך לנכות משכרו לעשות לו ניסים ונפלאות לבניו ולהוציאם ברכוש גדול לזה הבטיחו סמוך לאמירת יצאו וגו' **ואתה תבוא אל אבותיך בשלום** שלא יתנכה משלום אשר החזקת במעוז, וחסד הבטחון מתת אלהים הוא וזה כנגד הבטחות השארות הנפש, וכנגד פרטי עולם הזה אמר **תקבר בשיבה טובה** כאן כלל שלא יביט מהשעבוד לבניו גם שיעשה ישמעאל תשובה כדי שיקברוהו בשיבה טובה בבנים צדיקים כי הוא המקווה לצדיקים ושאר פרטי הטוב והשלוה. ובזה סלקה קושית רמב''ן יעוין שם דבריו, כי לא באה ההבטחה על הגירות וכו' ודברי רמב''ן דחוקים:
@78 **ודור רביעי וגו' כי לא שלם**. צריך לתת לב בטעם זה. והנה רש''י ורמב''ן נחלקו בפי' דור רביעי, רש''י ז''ל פי' רביעי לגולים יהודה פרץ חצרון, וכלב בן חצרון היה מבאי הארץ. ורמב''ן ז''ל דחה דברי רש''י ופי' דור רביעי לאמורי כי ה' פוקד עון אבות על שלשים ועל רבעים. וקשה לי גם לדברי רמב''ן כי לאיזה ענין מודיע ה' דבר זה לאברהם. וגם אינו רמוז התנאי בדברי ה' שאם ישובו האמורי לא יחרימם שהוא עיקר הודעת דור רביעי לדבריו. ועוד אם דור רביעי דאמורי הוא לא היה צריך לחזור להזכירו אחר כך באומרו עון האמורי כיון שבו הוא מדבר בסמוך. ופשוט שאין דברי רמב''ן מחוורים, והנכון הוא שיכוין ה' לומר שני קיצים האחד הוא קץ הגלות והשיעבוד והעינוי שיצטרף הכל למנין ת' וכשיגיע ת' שנה נשלמה הגזירה והוציא ה' אותם ממצרים בעצם היום שנשלמו הת', וקץ ב' הוא לביאת הארץ שלא תהיה כניסת הארץ בתשלום הת' אלא עד דור אחר שהוא דור רביעי. והוי יודע כי דורו של כלב דור ג' יחשב והוא שיצא ממצרים והגם כי כלב נכנס לארץ אין הדור נחשב אלא ברובו וכלב הוא לבדו נשאר מהדור דכתיב (במדבר יד ל) כי אם כלב בן יפונה. וכשאמר הקב''ה דור רביעי על כללות בני ישראל הוא אומר, ואין דברי רש''י מחוורין במה שאמר בזה אלא דור רביעי הם דור שיצאו ממצרים פחות מכ' שנה שהם נכנסו לארץ שהם בני כלב והם רביעי לגזירה כשתחשוב פרץ חצרון כלב ישר ושובב בני כלב הם דור רביעי שבו לארץ כנען, כי אין למנות הדורות מהשבטים כמו שהתחיל למנות רש''י יהודה פרץ וכו' שאם באנו להתחיל מיום שהתחילה גזירת ת' נחשוב גם יצחק ואם באנו להתחיל מראשון אדם שירד למצרים נחשוב מיעקב ויהיה כלב ה' אלא ודאי שאין למנות הדורות אלא משהתחיל השיעבוד שהיו ישראל שלא ברשות עצמם וזה היה אחר מיתת השבטים שאז התחיל השעבוד כאומרם ז''ל (שמו''ר פ''א) שכל זמן שהיו השבטים בעולם לא טעמו שעבוד וכהם כאבותם, וה' רמז זמן שיתחיל חשבון הדורות באומרו **ישובו הנה**, דקדק לומר תיבת **ישובו** לומר שבמעוכבים ביד מושל הוא אומר ישובו כשישלימו ד' דורות, ודור ראשון שתקף עליו יד מושל הם בני השבטים שהשבטים ברשות עצמן היו ואת בניהם שבו המצרים לבל עלות מן הארץ והבן ועיקר:
@78 **ומעתה** נשקיף להבין אמרי קדוש ינובב חכמה באומרו **כי לא שלם עון האמורי** אם כן מוכח שעון האמורי מעכב הכניסה ובמעשה אשר סדר ה' בתורתו הנעימה יגיד כי עון המרגלים הוא אשר סבב עכבת דור היוצא ממצרים עד תומו ואת בניהם הביא שמה וזולת המרגלים שהרשיעו היו נכנסים הדור היוצא בשנה שניה ליציאת מצרים שהוא סוף הת' ולא הלכו המרגלים אלא להפקת רצון השואלים לרגל וזולת זה אמר ה' להם שיכנסו באותו דור עצמו שיצא ממצרים שהוא ג' והלא לא שלם עון האמורי עדיין כמאמרו יתברך:
@78 **אכן** כוונת הכ' היא על דרך אומרם ז''ל במסכת ברכות (ז:) פרק ראשון בפסוק (חבקוק א) כבלע רשע צדיק ממנו צדיק ממנו בולע צדיק גמור אינו בולע ע''כ. פירוש כי אם יהיה רשע עדיין יש בידו קצת זכות ויבא צדיק שרובו זכיות להתגרות בו אין כח בצדיק לאבדו כי עדיין יש לרשע להשתלם זכות הנשאר לו בעולם הזה והרשע יתנקם מהצדיק להיות שיש ביד הצדיק מהתיעוב שאינו צדיק גמור, אבל כשיהיה גמור הגם שישאר לרשע חלק מהטוב יופקע כלילתו, וכן אם יהיה הרשע מוחלט ונגמר דינו למות בכל עושה ה' שליחותו לאבדו וכל הקודם בו זכה ואפילו אינו צדיק גמור יכול לאבדו מן העולם:
@78 **והנה** בצאת ישראל ממצרים וכששלחו המרגלים היו במדרגת צדיקים גמורים, והגם שעשו העגל, כבר נענשו עליו, והשמצה אין בו שיעור שימנע מהם שם צדיק גמור לענין זה שלא יקראו צדיקים **גמורים** בערך האמורי והן הנה דור חסיד (סנהדרין קי:) דכתיב (תהלים נ) אספו לי חסידי כורתי וגו' אשר לא כן היו אחר שליחות המרגלים שהקניטו את ה' והמרו וכו' ואז נכנסו בגדר צדיק ממנו בערך האמורי, ולכן כשהיו צדיקים גמורים קודם המרגלים היה בהם כח לדחות האמורי כי יאמרו אליו פנה מקום מארצנו אשר נתן לנו ה' וכשלא ירצה הרי זה מורד ובן מות הוא מה שאין כן אחר שחטאו והמרו אמרי אל לא נשארו בחזקת צדיק גמור, ולהיות שעדיין לא שלם עון האמורי אין בידם להשמידו, ולזה תמצא כשהעפילו לעלות ההרה יצא האמורי ורדפום ויכום כאשר תעשנה הדבורים וזה יגיד בלע רשע צדיק ממנו. ותמצא עוד שבכניסתם אמר משה (עקב ט ה) לא בצדקתך וגו' כי אם ברשעת הגוים האלה כי נשלם עונם. וכפי זה הגם שאינכם צדיקים גמורים אתה בא לרשת וגו'. כי אין לו שום זכות ליאמר עליו צדיק ממנו. כי משמעות צדיק ממנו יורה שיש לו קצת זכות שיוצדק ליאמר צדיק ממנו אבל מוחלט ברשע אין לו חלק הצדקות ליאמר צדיק ממנו והבן. ומעתה יתפרשו דברי ה' על נכון **ודור רביעי** וגו' פי' מבטיחו הבטחה שאין לה ביטול בשום אופן בעולם ונתן טעם לדבר יתברך שמו ובנתינת הטעם **כי לא שלם** וגו' ואתה תשכיל לדעת כי לא יספיק טעם זה אלא לזמן שהיו ישראל בהעדר שם צדיק גמור ואז לצד שעדיין לא שלם עונו של אמורי לא יוכלו בא לארצו אבל אם יהיו ישראל במדרגת צדיק גמור אין מניעות שלימות העון תמנעם מבוא לרשת ארצו, ולזה כשיצאו ממצרים וקבלו התורה נתרצה האל שיכנסו לארץ תכף ומיד ויקחו את ארצו כי יתגרו בהם ויתקנאו בעושי רשעה, מה שאין כן אחר עון מרגלים נכנסו בגדר צדיק ממנו לזה איחר ה' עד תום כל הדור וביני ביני ישלים עון האמורי, ואם לא היה טעם שלימות עון האמורי היו בניו נכנסים תיכף ומיד ועונם יפרעו בעונשים אחרים כאשר ישפוט השופט בצדק:
@80 **ביום ההוא כרת וגו'**. אומרו **נתתי** לשון עבר, לפי מה שקדם לנו שהחזיק בה אברהם כמו שפירשנו במקומו (לעיל י''ג ט''ו) יוצדק לומר נתתי כבר כי הבנים יזכו מדין יורש:
@80 **הנה** יש לתמוה איך טח מראות עיניהם של הממאנים להאמין בגדולתינו ומעלתינו העתידה לבא, כי מקרא מלא דבר הכתוב שכרת ה' ברית עם אברהם אבינו עליו השלום לתת לזרעו עשרה אומות ועד עתה לא מצינו שנתן ה' לישראל אלא ז' אומות ונשארו ג' אומות ואיך יאמרו העצמות היבשות אבדה תקות נחלתינו ושבועת ה' מנגדתם, וגם הז' שנתן ה' לא כולם באו לפרק התקבל ובעונותינו עבדים משלו בנו, ועשה ה' ככה לרמוז מדה כנגד מדה כשם שאנו עבדי ה' ואין נכנעים לו ית' כעבד מורד ברבו גם כן יבואו עבדים שלנו וימרדו בנו. ועוד יש לאלוה מילין לקיים בריתו. עוד נתתי לבי לתור בסדר הכתובים ואראה כי הקדים הקיני והקניזי והקדמוני שהם עמון ומואב ואדום שלא באו לידינו בראשונה אלא ז' המאוחרים ואין נכון להקדים המאוחר, אכן ודאי כי מאת ה' היתה זאת להעירך ולהגיד לך כי עיקר הנתינה היא העתידה שיבואו יחד הג' ועמם הנותר מהז' אומות ותקפוץ פיה עולה בראות שבועת ה', וסימן לדבר נתינת הד' מלכים אשר נתן ה' לאברהם ג' כנגד קיני וקניזי וקדמוני והרביעי תדעל מלך גוים רמז אל התאספות הגוים הנשארים בהשבעה הראשונים והבן:
@88 **ותאמר שרי חמסי וגו'**. צריך לדעת למה מסרה דין שרה על אברהם והוסיפה לפרט ולומר חמסי עליך שנרא' שנתכוונה למעט הזולת, ואם על הגר נתכוונה אין בדבריה נכונה לפי הנראה כי הגר היא שהקילה בכבוד גבירתה ועליה תלונתה לא על אברהם. עוד צריך לדעת כוונת דברי אברהם אשר השיב **הנה שפחתך** וגו' שנראה שקבל קבלת שרי אלא שהוא מתקן מכאן והלאה ואם לא פעל און היה לומר מה תריב אלי:
@88 **אכן** יתבאר הענין בהקדים דבריהם ז''ל (ב''ר פמ''ה) וז''ל ולה שפחה מצרית שפחה מלוג היתה והיה חייב במזונותיה ולא היה רשאי למוכרה. בעי ריש לקיש מהו דתניא מלוג אמר להון כמה דאת אמר מלוג מלוג ע''כ. הרי דהגר היתה גופה קנוייה לשרה ופירותיה לאברהם למולגם. ובענין בני שפחת מלוג אם ילדה נחלקו במם' כתובות דף ע''ט חנניה וחכמים חכמים או' ולד מלוג לאשה והטעם משום דחיישינן למיתה והקרן כלה. וחנניה סובר לבעל דלא חיישינן למיתה. עוד אמרינן בגיטין דף ל''ט אמר רבי אשי אמר רב עבד שנשא בת חורין בפני רבו עשאו בן חורין ומפרש לה הש''ם בשהשיאו רבו בת חורין ע''כ. ומפרשים שם משום שמן הסתם שחרריה דאם לא כן לא היה עושה על ידו עבירה להשיאו בת חורין ע''כ, והוא הדין שפחה שהשיאה רבה לבן חורין עשאה בת חורין, וכתב מה''ר יוסף קארו ביורה דעה הלכות עבדים סימן רס''ז וזה לשונו הבא על שפחתו עשאה בת חורין ודוקא לשם אישות אבל שלא לשם אישות לא עשאה בת חורין ע''כ. והנה בבא עליה סתם נחלקו הרי''ף והרמב''ם, להרי''ף (יבמות פ''ב) מן הסתם גם כן עשאה בת חורין ולהרמב''ם (הל' עבדים פ''ט) לא עשאה בת חורין אלא אם כן פירש לשם א ישות:
@88 **ובזה** נבא לביאור הענין, כי בראות שרה כי הגר מזלזלת בכבודה רגזה ורעשה היתכן כי שפחה תקל גבירתה, ומן הסתם אברהם הרגיש בדבר ממה שמתרעמת שרה עליו קודם הודעת הדבר אליו, והגם שאמרה אחרי כן אין זה דרך הודעה אלא דברי התרעמות והידיעה כבר הכירה שידע, ודנה בזה ב' חילוקי דינים הא' שאברהם גילה בפירוש שבא עליה לשם אישות או הגם שבא עליה סתם חושבת הגר שהיא בת חורין ודעתה כהרי''ף. והב' הוא שחשבה בדעתה הגר שיצתה לחירות מדין שאמרו בגיטין שכתבנו בסמוך עבד שנשא בת חורין בפני רבו יצא לחירות וכן להפך שפחה שנשאת לבן חורין עשאתה גבירתה בת חורין ובזה פקע עבדות מהגר. ולזה צעקה בפני אברהם כי עליו תלונתה ולא על הגר כי הגר כפי הדין שחושבת בדעתה אין להאשימה אבל חמסי עליך שאתה מסכים על דעתה שלא כפי הדין. ואמרה טענות לסתור ולנתוש צדדי הדינים שמהם יצא הטעות לחירות הגר, והוא אומרה **אנכי נתתי שפחתי בחיקך** פי' שפחה זו שלי היא ואין לך בה אלא מליגת פירות, ולו יהיה שתבא עליה בפי' לשם אישות אין לה בזה דין שיחרור כי אינה שפחתך לשחררה והגם שתאמר כן בפירוש. ואם לצד טענת המשיא שפחתו לבן חורין וכו' וזו נתתיה לך לאשה שאתה בן חורין דוקא אם נתתיה סתם וכמו שנתנו הטעם שמן הסתם לא יעבור על לאו דלא תהיה קדשה ולא יהיה קדש שהוא אזהרה לבן חורין וכו', אבל אנכי לא הנחתי הדבר סתם אלא פירשתי לך הדברים בפי' שלא שחררתיה אלא עודנה שפחתי הגם שהיא בחיקך. וכמו כן תמצא בדבריה הראשונים אליו שאמרה לו בא נא אל שפחתי פי' אחר שיבא עליה עודנה שפחתה שהיה לה לומר בא נא אל הגר:
@88 **שוב** מצאתי מדרש רבותינו ז''ל ברבות (ב''ר פמ''ה) וז''ל ותתן אותה לאברם אישה ולא לאחר ע''כ. הנה רז''ל דקדקו תיבת אישה שלא היה צריך לאומרה ויישבו שלמעט בא, וצריך לדעת מיעוט זה למה הוצרך. ולפי דברינו צריך הדבר ליאמר לומר שעדיין היא שפחתה ולא נתנתה אלא לאברהם. ואם ירצה אברהם לתתה לאחר או לשלחה לעצמה לעשות כטוב בעיניה אין לו רשות הא למדת שעודנה שפחתה. ואברהם הודה לדבריה שהדין עמה בטענתה ויש בזה שני דרכים. הא' **אפשר** שאברהם כמו כן היה דעתו מתחילה ועד סוף ואפילו הכי בא עליה לטעם אשר אבאר. או לא חשב כן מתחלה ודעתו היתה כי לשם אישות בעל ומשוחררת היא כי לא חשב שנתכוונה **שרה** למה שגלתה דעתה עתה, ואילו חשב כן אפשר שלא היה בא עליה מדין (דברים כג) לא יהיה קדש, וכן תמצא שבמשך י''ד שנה משנולד ישמעאל עד שנולד יצחק לא יסף עוד לדעתה:
@88 **וטעם** שרה שלא הקפירה לתת **שפחה** לבן חורין וגם אברהם למה שנאמר שהבין דברי שרה ולא חש על עצמו, דע כי לפי הפשט נוכל לומר שעדיין לא נצטוו על זה. והגם שהיו מדקדקים לקיים אפי' דקדוקי מצות של חכמים, לצד הנבואה היו עוברים על המצות לפי שעה. וכבר כתב רמב''ם בספר המדע בפרק ט' מהלכות יסודי התורה כי אם יבוא נביא במאמרו יתברך שיעברו ישראל ואפי' רבים על עבירה אחת לפי שעה כי מותר לעשות כן וכאליהו בהר הכרמל (מ''א יח) וכמו כן עשה אברהם על פי שרה כי נביאה היתה יותר מאברהם כמאמרם ז''ל (שמו''ר פ''א) בפסוק כל אשר תאמר אליך שרה שמע בקולה, ולזה כשאמרה לו בא נא אל שפחתי הסכים לדברי **הנביאה**. וצורך היה בדבר להיות כן כי באמצעות היותה שפחתה נתברר בה חלק המאום שהיה דבוק באברהם מימי קדם ויצאה הזוהמא בישמעאל ונשאר אור שלם ונכון ביצחק, ואלו היתה הגר משוחררת לא היה יוצא כל הזיהום לבד מבלי שיצא עמו חלק הטוב ופרצה גדולה היתה מסובבת מהדבר וה' יתברך עשה נפלאותיו אלינו. ואולי כי לזה נתכוונה שרה באומרה **ישפוט השופט ביני ובינך** כי חששה שיאמר אברהם ואיך תסכים עליו להיות קדש, לזה אמרה, הוא השופט ישפוט בינו ובינה וכו'. ותיכף הודה לדבריה ע''ה, וכשידעה שרה כי אין **סתירה** לטענותיה ועודנה שפחתה **ותענה שרי**, **ותברח** וגו' פי' כי הגר לא קבלה הדין וחשבה שעברו עליה את הדרך ודין בת חורין יש לה לצד שגבירתה נתנה אותה לבן חורין האדם הגדול אברהם אבינו עליו השלום ודאי יצתה לחירות, והוא לא **שמעה** התנאי שהתנית שרה, לזה ברחה לה ויפגעו בה בני האלהים והודיעוה כי היא שפחת שרי ותקבל עליה את הדין ואמרה **מפני שרי גבירתי** וגו':
@88 **ויש** לדון בישמעאל אם יש לנו איזה קנין בו או לא, תניא בתורת כהנים פרשת בהר סיני וז''ל מנין אתה אומר ישראל שבא על שפחתו וילדה ממנו בן מותר אתה לשעבדו עבד, תלמוד לומר אשר יהיו לך מאת הגוים אשר סביבותיכם ולא מן הכנענים שבארץ עכ''ל. פי' שלא היה צריך לומר אשר יהיו לך וגם משמעות תיבת יהיו לך. דחוקה שהיה לו לומר אשר תקנה ומזה דורש אשר יהיו לך פי' תוליד אתה מאת הגוים דהיינו ישראל שבא על שפחתו, ואומרם ולא מן הכנעני וכו' פי' כי זה יש בו דין (דברים כ) לא תחיה כל נשמה, ומעתה יצא הדין כי ישמעאל וזרעו קנויים לנו קנין גמור, לא מבעיא לסברת רבנן שבן שפחת מלוג לאשה ואנו יורשי שרה, אלא אפילו לסברת חנניה הרי נתן אברהם את כל אשר לו ליצחק וישמעאל בכלל ולנו הוא עם העמים אשר כרת ה' ברית לתת לנו, ומכללם הוא אדום הוא וחלקו בישמעאל. והעד הנאמן לדברינו הוא מה שאמר הבורא יתעלה (כ''א י''ג) וגם את בן האמה הרי שקראה אמה וקראו בנה ולא בנו, כי תמצא בבני השפחות בלהה וזלפה דקדק הכתוב לומר בהם ותלד ליעקב בן, (ויצא ל') וכן אמר בשני בן שני ליעקב, וכן בג' אמר ותלד זלפה שפחת לאה ליעקב בן, וכן בד' אמר בן שני ליעקב, הרי שבכולן דקדק לכנותם בשם בני יעקב כי נשתחררו וכאן אמר ה' להפך בן האמה ואמר לו עוד כי ביצחק יקרא לך זרע:
@88 **ואין** זה בכלל עשרה עממין אשר אמר ה' אותם אתן לכם כי זה זכינו בו משלנו ואין צורך נתינה בו:
@104 **ולא יקרא וגו' והי' שמך וגו'**. במדרש ב''ר אמרו (פמ''ד) וז''ל ויאמר אברם הן לי אמר ר' שמואל בר יצחק המזל דוחקני ואומר לי אברם אין אתה מוליד אמר לו הקדוש ברוך הוא כדבריך אברם אינו מוליד אברהם מוליד שרי לא ילדה שרה תלד עכ''ל. קשה הרי מצינו שילד אברהם את ישמעאל קודם שנקרא שמו אברהם:
@104 **עוד** צריך לדעת אומרו שרי לא ילדה וכו' נדרשתי ללא שאלו שהרי לא טען אלא אברם. לא היה לו להשיב אלא אברם וכו' כי שרי מי הזכירה:
@104 **ונראה** להיות שעיקר בנים של אברהם הם אשר תוליד לו שרה דכתיב כי ביצחק וגו' ואברהם אבינו ע''ה ידע זה ברוח הקודש כי ישמעאל אינו אלא בירורי פסולתו של יצחק וראה במזל כי עיקר זרעו לא יצא לעולם כי מן הסתם לא יגיד המזל אלא על איש עם בת זוגו, ולזה אמר אברם אינו מוליד כי לידת ישמעאל אינו לידה כאומרו כי ביצחק יקרא לך זרע, ובזה יתיישב למה בתשובת ה' אליו הזכיר שרה כי היא עיקר לידת אברהם:
@117 **ויאמר אברהם וגו' לו ישמעאל וגו'**. יכוין בתפלה זו שיהיה ישמעאל הולך בצדק לפני ה', וזה הוא **יחיה לפניך** שהצדיקים קרויים חיים. ואומרו **לפניך** על דרך אומרו ואתם הדבקים בה' וגו' והוצרך לתפלה לפי שראה בו סימנים לא טובים שעל כל פנים לא תהיה רשעת הרשע נעלמת מעיני הצדיק ומה גם בנו, לזה התפלל עליו שיהיה צדיק, וגילה דעתו כי הוא זה מבוקשו וכמו שפירשתי בפסוק (ט''ו ג') הן לי. והבטיחו ה' שיהיה זרעו ככוכבים ושואל שתתקיים הבטחה זו בישמעאל:
@118 **ויאמר אלהים אבל שרה וגו'**. צריך לדעת טעם אומרו אבל כי אין לה משמעות:
@118 **ונראה** שנתכוין לומר אליו אין הכי נמי אם הנתינה היא בשבילך לבד יש לך פה לומר שאתה מסתפק בישמעאל, אבל שרה אשתך יולדת פי' לצד שתלד שרה אינך רשאי לוותר בשל הזולת ודקדק לומר לך פי' שיהיה לה בן ממך כתפלתה שכל בנים שיהיו לה יהיו ממך. עוד אפשר לומר כי ה' הקפיד על שאמר לו ישמעאל שבחר בישמעאל. ואפשר כי זה היה סיבה שניתן לו יצחק מסטרא דנוקבא, והוא אומרו שרה יולדת, ונצטער הרבה מצד זה כשעקד אותו על גבי המזבח כי על ידי העקידה ניתנה לו הנפש היולדת ונולדה לו אז רבקה בת זוגו:
@119 **ולישמעאל שמעתיך וגו'**. הכונה להיות שאברהם לא התפלל על ישמעאל אלא לצד שהוא לבדו זרעו מה שאין כן אחר שנתן לו ה' זרע משרה אז לא יבקש עוד על ישמעאל לזה אמר לו הקב''ה ולישמעאל שמעתיך פי' קבלתי דבריך והוא על דרך אומרם ז''ל (מכות יא.) קללת חכם אפילו על תנאי מתקיימת ומרובה מדה טובה ממדת וכו' ולפי מה שפירשתי שתפלת אברהם על ישמעאל היתה שיהיה צדיק רמז לו ה' שיחזור בתשובה כאומרו הנה ברכתי אותו שיחזור בתשובה שהברכה הוא שיהיה נכלל בברוך וברוך הוא מקור הקדושה. ואמר לשון עבר **ברכתי** וגו' הוא מה שרמז באומרו (טו) תקבר בשיבה טובה, וכן היה כאומרם ז''ל (ב''ר פל''ח) שעשה תשובה:
@122 **ויקח אברהם וגו'**. להיות שישמעאל היה גדול בן י''ג שנה לזה הוצרך לקחתו ברברים להתרצות לו. וגם לילידי ביתו ומקנת כספו כי היה בהם גדולים ולקחם בפיום כי רצה שכולם יקבלו עליהם ברצונם מצות המלך:
@122 **כאשר דבר וגו'**. צריך לנו לדעת למה הוצרך לומר כאשר דבר וגו' רואה אני כי כן עשה. ואולי שיכוין לומר שאותו מעשה שלקח אותם בריצוי הוא כאשר דבר אתו אלהים:
@122 **עוד** יכוין לומר שלא נתעכב מעשות מצות ה' אלא תכף ומיד **כאשר דבר** פירוש סמוך, וזה להודיע זריזותו ע''ה בעבודת הקב''ה:
@122 **עוד** יכוין לומר על דרך אומרם ז''ל (ע''ז כז.) המול ימול שצריך המל שיהיה הוא עצמו נימול. וזה הוא שאמר **כאשר דבר אתו** פי' שקדם הוא ומל עצמו תחלה ואחר כך מל האחרים. וכפי זה לא קשה למה לא הזכיר הכתוב מילת אברהם כי מב' טעמים יש לו להקדים עצמו, בין מצד הזריזות קשוט עצמך וכו', בין מצד כדי שימול אותם כהלכה אשר צוהו ה' המול ימול, ומה שאמר הכתוב אחר כך ואברהם בן צ''ט שנה וגו' זה להודיע הזמן שבו נימול כשם שאמר וישמעאל בן י''ג אף על פי כן הזכירו קודם. ולמה שפירשתי לא קשה כי השמיענו הכתוב שהוא מל עצמו תחלה כמ''ש כאשר דבר אתו וגו' על אופן שפירשתי:
@122 **חסלת פרשת לך לך**
